window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["sugar2"]={"id": "sugar2", "title": "糖代谢(二)", "sub": "93页教材逐页详解 · 86张概念图 · 24道考题", "sub2": "糖异生 · 糖原合成与分解 · 血糖调节", "modules": [{"i": 0, "name": "模块一：糖的合成代谢与糖异生", "slides": [{"i": 0, "sec": "糖代谢(二)", "title": "糖的合成代谢 章节页 (p1)", "notes": "第五节 糖的合成代谢。\u000b内容：一、糖原的合成；\u000b二、淀粉的合成；\u000b三、蔗糖的合成；\u000b四、糖异生作用(gluconeogenesis)。\u000b本节全面阐述：非糖物质→糖，以及糖原/淀粉/蔗糖的生物合成途径。", "page": 1, "level": "掌握", "img": "assets/img/sugar2/p001.jpg", "anim": null, "fig": "", "points": ["①糖合成代谢四大内容：糖原、淀粉、蔗糖、糖异生", "②主线：非糖物质→糖；葡萄糖→多糖/二糖", "③糖异生是唯一从非糖物质生成葡萄糖的途径"], "check": null, "cards": null}, {"i": 1, "sec": "糖代谢(二)", "title": "糖合成代谢总览 (p2)", "notes": "糖的合成代谢全景：非糖物质(丙酮酸/乳酸/甘油/生糖aa)→糖异生→葡萄糖。\u000b葡萄糖→G-6-P→G-1-P→UDPG→糖原/淀粉合成；\u000b或→F→蔗糖合成。\u000b5-P-核糖→PPP提供合成前体。\u000b合成分支正好补齐分解代谢的全景图。", "page": 2, "level": "掌握", "img": "assets/img/sugar2/p002.jpg", "anim": null, "fig": "", "points": ["①糖异生：丙酮酸/乳酸/甘油/生糖aa→葡萄糖", "②葡萄糖→G-6-P→G-1-P→UDPG→糖原/淀粉", "③UDPG+F→蔗糖；PPP提供核糖等前体", "④合成与分解途径互补构成全景"], "check": null, "cards": null}, {"i": 2, "sec": "糖代谢(二)", "title": "葡萄糖的活化-UDPG (p3)", "notes": "一、糖原的合成(一)葡萄糖的活化：G→G-6-P(己糖激酶)→G-1-P(变位酶)+UTP→UDPG(尿苷二磷酸葡萄糖)+PPi。\u000b无机焦磷酸酶水解PPi→2Pi→驱动反应不可逆！\u000bUDPG是活化的葡萄糖基供体(高能糖基载体)，不是G-1-P本身。", "page": 3, "level": "掌握", "img": "assets/img/sugar2/p003.jpg", "anim": null, "fig": "", "points": ["①活化三步：G→G-6-P→G-1-P→UDPG", "②UTP参与，PPi被焦磷酸酶水解驱动不可逆", "③UDPG是活化葡萄糖基供体，非G-1-P"], "check": null, "cards": null}, {"i": 3, "sec": "糖代谢(二)", "title": "α-1,4糖苷键的形成-糖原合酶 (p4-p5) (p4)", "notes": "(二)α-1,4键形成：nUDPG+引物(麦芽四糖/小糖原分子)→糖原合酶→(Glc)n+1+nUDP。\u000b注意合酶(synthase)需ATP,磷酸化后失活;合成酶(synthesase)不需ATP。\u000b引物由糖原引物蛋白(glycogenin)携带→自催化加入第一个Glc。\u000b糖原合酶从非还原端延伸→α-1,4线性链。", "page": 4, "level": "掌握", "img": "assets/img/sugar2/p004.jpg", "anim": null, "fig": "", "points": ["①糖原合酶催化UDPG+引物→α-1,4延伸", "②合酶需ATP磷酸化后失活，合成酶不需ATP", "③引物由glycogenin自催化加第一个Glc", "④从非还原端单向延伸"], "check": null, "cards": null}, {"i": 4, "sec": "糖代谢(二)", "title": "α-1,6分支键-分支酶 (p6)", "notes": "(三)α-1,6键形成：分支酶→切开一段α-1,4线性链(6-7个G残基段)→转移到同链或邻链的OH-6→形成α-1,6分支。\u000b糖原多分支意义：①增加溶解性(非短链螺旋→无定形结构);②增加非还原端数目→酵解酶多点同时攻击→糖原快速降解释能。", "page": 6, "level": "掌握", "img": "assets/img/sugar2/p006.jpg", "anim": null, "fig": "", "points": ["①分支酶切6-7个G残基段转移至OH-6", "②形成α-1,6分支", "③分支意义：增溶解性、增非还原端、加速降解"], "check": null, "cards": null}, {"i": 5, "sec": "糖代谢(二)", "title": "淀粉的合成-ADPG (p7)", "notes": "二、淀粉的合成(一)α-1,4键形成(直链淀粉)：nADPG(腺苷二磷酸葡萄糖)+引物(麦芽糖等小淀粉)→淀粉合酶→(Glc)n+nADP。\u000b可在非还原端或还原端加入→双向延伸(与糖原仅单向不同)。\u000bADPG是植物淀粉合成的活性前体(与动物UDPG不同)。", "page": 7, "level": "理解", "img": "assets/img/sugar2/p007.jpg", "anim": null, "fig": "", "points": ["①淀粉合成用ADPG作活性前体（植物）", "②淀粉合酶催化α-1,4键形成直链淀粉", "③可双向延伸，与糖原单向不同"], "check": null, "cards": null}, {"i": 6, "sec": "糖代谢(二)", "title": "支链淀粉合成-Q酶 (p8)", "notes": "(二)α-1,6键形成(支链淀粉)：Q酶→切段→转移至OH-6→形成α-1,6分支。\u000bQ酶作用与糖原合成中分支酶类似→每25-30Glc一分支为支链淀粉特征。\u000bQ酶决定了淀粉溶解度和酶消化速度。\u000b直链淀粉无分支,支链淀粉有a-1,6支点。", "page": 8, "level": "理解", "img": "assets/img/sugar2/p008.jpg", "anim": null, "fig": "", "points": ["①Q酶切段转移至OH-6形成α-1,6分支", "②每25-30个Glc一分支为支链淀粉特征", "③Q酶决定溶解度与消化速度", "④直链无分支，支链有α-1,6支点"], "check": null, "cards": null}, {"i": 7, "sec": "糖代谢(二)", "title": "蔗糖的合成概述 (p9-p10) (p8)", "notes": "三、蔗糖的合成：甜菜/甘蔗中贮藏形式。\u000b两条途径：(主)UDPG+F-6-P→磷酸蔗糖合酶→6-磷酸蔗糖+UDP→6-P蔗糖磷酸酶→蔗糖+Pi。\u000bUDPG+F→蔗糖合酶→蔗糖+UDP(次要途径)。\u000b磷酸蔗糖合酶是主要调控酶。", "page": 8, "level": "掌握", "img": "assets/img/sugar2/p008.jpg", "anim": null, "fig": "", "points": ["①蔗糖是甜菜/甘蔗的贮藏形式", "②主途径：UDPG+F-6-P→磷酸蔗糖合酶→6-P蔗糖→蔗糖", "③次途径：UDPG+F→蔗糖合酶→蔗糖", "④磷酸蔗糖合酶为主要调控酶"], "check": null, "cards": null}, {"i": 8, "sec": "糖代谢(二)", "title": "蔗糖合成途径图解 (p11)", "notes": "蔗糖合成分步：UDPG+F-6-P→磷酸蔗糖合酶→6-磷酸蔗糖+UDP→6-P蔗糖磷酸酶(Pi)→蔗糖。\u000b蔗糖=α-Glc(1→2)-β-Fru。\u000b两个异头碳均参与糖苷键→无还原性(已在糖代谢-1中讲解)。\u000b植物叶绿体合成→胞质。", "page": 11, "level": "理解", "img": "assets/img/sugar2/p011.jpg", "anim": null, "fig": "图示蔗糖合成的两步酶促反应：先由UDPG提供葡萄糖基给F-6-P，再脱磷酸生成蔗糖，注意两异头碳均参与糖苷键故无还原性。", "points": ["①UDPG+F-6-P经磷酸蔗糖合酶生成6-磷酸蔗糖", "②6-P蔗糖磷酸酶水解出Pi，生成蔗糖", "③蔗糖为α-Glc(1→2)β-Fru，两异头碳成苷无还原性", "④合成在植物叶绿体，后转至胞质"], "check": null, "cards": null}, {"i": 9, "sec": "糖代谢(二)", "title": "糖异生定义与总览 (p12)", "notes": "四、糖异生作用(Gluconeogenesis)。\u000b定义：丙酮酸/甘油/乳酸及生糖氨基酸等非糖物质→葡萄糖或糖原。\u000b部位：肝(主要),肾皮质。\u000b基本为酵解逆过程→但需绕过3个不可逆步骤。\u000b糖异生消耗6ATP(非酵解的2ATP回收)。", "page": 12, "level": "掌握", "img": "assets/img/sugar2/p012.jpg", "anim": null, "fig": "", "points": ["①定义：非糖物质（丙酮酸、甘油、乳酸、生糖氨基酸）合成葡萄糖/糖原", "②主要部位肝，其次肾皮质", "③基本为酵解逆过程，需绕过3个不可逆步骤", "④消耗6ATP，非酵解2ATP的简单回收"], "check": null, "cards": null}, {"i": 10, "sec": "糖代谢(二)", "title": "糖异生全途径图 (p13)", "notes": "糖异生全程：①丙酮酸/Lac/Ala/Ser等→丙酮酸→OAA→PEP(绕过PK)。\u000b②甘油→3-P-甘油→进入EMP逆方向。\u000b③Asp/Glu→OAA/a-KG→进入TCA→OAA→PEP。\u000b④所有C骨架汇入F-1,6-BP→F-6-P(绕过PFK)和G-6-P→G(绕过HK)完成糖异生。", "page": 13, "level": "掌握", "img": "assets/img/sugar2/p013.jpg", "anim": null, "fig": "全途径图展示四类前体如何汇入糖异生：乳酸/丙氨酸等经丙酮酸→OAA→PEP，甘油经磷酸二羟丙酮，天冬氨酸/谷氨酸经TCA中间物，最终绕过三个不可逆酶生成葡萄糖。", "points": ["①丙酮酸/Lac/Ala/Ser→丙酮酸→OAA→PEP，绕过PK", "②甘油→3-P-甘油进入EMP逆方向", "③Asp/Glu→OAA/α-KG→TCA→OAA→PEP", "④各碳骨架汇入F-1,6-BP，绕过PFK和HK完成糖异生"], "check": null, "cards": null}, {"i": 11, "sec": "糖代谢(二)", "title": "绕过PK-丙酮酸羧化酶 (p14-p15) (p12)", "notes": "⑧第一步绕过(最重要)：丙酮酸+CO2+ATP+H2O→丙酮酸羧化酶(生物素辅基,线粒体)→OAA+ADP+Pi。\u000bOAA→苹果酸(出线粒体)→OAA→PEPCK→PEP+CO2+GTP(GDP)(胞质)。\u000b需2步：羧化→再脱羧→总需1ATP+1GTP=可恢复丙酮酸的PEP。\u000b生物素是CO2载体(Biotin-CO2)。", "page": 12, "level": "掌握", "img": "assets/img/sugar2/p012.jpg", "anim": null, "fig": "", "points": ["①第一步绕过PK：丙酮酸羧化酶（生物素辅基，线粒体）生成OAA", "②OAA→苹果酸出线粒体→OAA→PEPCK→PEP", "③羧化+脱羧两步，耗1ATP+1GTP", "④生物素作为CO2载体（Biotin-CO2）"], "check": null, "cards": null}, {"i": 12, "sec": "糖代谢(二)", "title": "绕过PFK和HK (p16)", "notes": "(2)F-1,6-2P+H2O→果糖二磷酸酶(FBPase-1)→F-6-P+Pi(绕过PFK)。\u000b(3)G-6-P+H2O→葡萄糖-6-磷酸酶(G-6-Pase,内质网)→G+Pi(绕过HK)。\u000bFBPase-1是糖异生限速酶之一→受AMP抑制/F-2,6-BP抑制(与PFK相反)。\u000bG-6-Pase仅在肝/肾有→肌肉不能释G到血(无G-6-Pase)。", "page": 16, "level": "掌握", "img": "assets/img/sugar2/p016.jpg", "anim": null, "fig": "", "points": ["①F-1,6-2P经FBPase-1生成F-6-P，绕过PFK", "②G-6-P经G-6-Pase（内质网）生成G，绕过HK", "③FBPase-1为限速酶，受AMP和F-2,6-BP抑制", "④G-6-Pase仅肝/肾有，肌肉不能释糖入血"], "check": null, "cards": null}, {"i": 13, "sec": "糖代谢(二)", "title": "糖异生总反应式与能量 (p17)", "notes": "总反应式：2丙酮酸+4ATP+2GTP+6H2O+2NADH→G+4ADP+2GDP+6Pi+2NAD+。\u000b消耗：4ATP+2GTP=7个高能磷酸键(2个GTP中的高能键在PEP合成中用)。\u000b净消耗：酵解产2ATP,糖异生消耗约6-7ATP→净亏4-5ATP→保证代谢高效单向性。", "page": 17, "level": "掌握", "img": "assets/img/sugar2/p017.jpg", "anim": null, "fig": "", "points": ["①总式：2丙酮酸+4ATP+2GTP+6H2O+2NADH→G+4ADP+2GDP+6Pi+2NAD+", "②消耗4ATP+2GTP=7个高能磷酸键", "③酵解产2ATP，糖异生耗6-7ATP，净亏4-5ATP", "④能量净亏保证代谢单向高效"], "check": null, "cards": null}, {"i": 14, "sec": "糖代谢(二)", "title": "糖异生前体物质 (p18)", "notes": "(二)糖异生前体：(1)生成丙酮酸类：乳酸(血)→Cori循环,生糖aa(Ala/Ser→葡萄糖-丙氨酸循环等)。\u000b(2)生成OAA类：TCA环中间物(植物乙酰CoA可通过TCA→OAA再糖异生),生糖aa(Asp→OAA,Glu→α-KG→OAA)。\u000b(3)生成酵解中间物类：甘油(→G3P)→进入F-1,6-BP以逆方向→G。", "page": 18, "level": "掌握", "img": "assets/img/sugar2/p018.jpg", "anim": null, "fig": "", "points": ["①生成丙酮酸类：乳酸（Cori循环）、生糖氨基酸（丙氨酸-葡萄糖循环）", "②生成OAA类：TCA中间物、Asp→OAA、Glu→α-KG→OAA", "③生成酵解中间物类：甘油→G3P→逆EMP方向生成糖"], "check": null, "cards": null}, {"i": 15, "sec": "糖代谢(二)", "title": "糖异生生理意义与问题 (p19)", "notes": "(三)糖异生生理意义：①十分重要的生物合成葡萄糖途径→脑组织100g/日需G主要来自糖异生。\u000b②饥饿/运动等→维持血糖→防止低血糖→保障脑组织供糖。\u000b问题：乳酸在肝中经TCA彻底氧化→完全氧化乳酸→净产约15ATP。\u000b乳酸→糖异生→G→供组织→能量回收利用极高效!", "page": 19, "level": "掌握", "img": "assets/img/sugar2/p019.jpg", "anim": null, "fig": "", "points": ["①糖异生是重要的葡萄糖合成途径，脑每日需100g葡萄糖主要靠它", "②饥饿/运动时维持血糖，防止低血糖，保障脑供糖", "③乳酸在肝经TCA彻底氧化净产约15ATP", "④乳酸→糖异生→葡萄糖供组织，能量回收高效"], "check": null, "cards": null}, {"i": 16, "sec": "糖代谢(二)", "title": "第六节-糖代谢调节 (p20)", "notes": "第六节 糖代谢调节。\u000b内容：一、无氧酵解的调节；\u000b二、TCA环的调节；\u000b三、酵解/TCA/氧化磷酸化三者协调；\u000b四、激素对糖代谢的调节。\u000b细胞通过多种机制精密调控糖代谢通量以适应能量需求变化。", "page": 20, "level": "掌握", "img": "assets/img/sugar2/p020.jpg", "anim": null, "fig": "", "points": ["①糖代谢调节涵盖酵解、TCA、氧化磷酸化及激素四条主线", "②核心是使糖代谢通量适应能量需求变化", "③三大途径需协调统一，非孤立调控"], "check": null, "cards": null}, {"i": 17, "sec": "糖代谢(二)", "title": "代谢调节基本原理 (p21)", "notes": "调节机制：通过影响限速酶的活性来促进/抑制反应途径。\u000b限速酶一般为别构酶(allosteric enzyme)→受别构效应剂调控：产物(反馈抑制)、底物(前馈激活)、核苷酸(ATP/ADP/AMP→反映能荷状态)。", "page": 21, "level": "掌握", "img": "assets/img/sugar2/p021.jpg", "anim": null, "fig": "", "points": ["①调节通过改变限速酶活性实现", "②限速酶多为别构酶，受别构效应剂调控", "③产物反馈抑制、底物前馈激活", "④ATP/ADP/AMP反映能荷状态"], "check": null, "cards": null}, {"i": 18, "sec": "糖代谢(二)", "title": "酵解调节-三酶调控 (p22)", "notes": "一、无氧酵解的调节。\u000b关键调控点对应三个不可逆酶：(1)己糖激酶：受G-6-P反馈抑制。\u000b★(2)磷酸果糖激酶(PFK-1)：最重要调控酶→ATP/柠檬酸/H+抑制(-)→AMP/ADP/F-2,6-BP激活(+)。\u000b(3)丙酮酸激酶(PK)：ATP/Ala抑制(-)→F-1,6-BP前馈激活(+)。\u000b三酶协同决定酵解通量。", "page": 22, "level": "掌握", "img": "assets/img/sugar2/p022.jpg", "anim": null, "fig": "", "points": ["①三个不可逆酶是酵解调控点：己糖激酶、PFK-1、PK", "②PFK-1最重要，ATP/柠檬酸/H⁺抑制，AMP/ADP/F-2,6-BP激活", "③己糖激酶受G-6-P反馈抑制", "④PK受ATP/Ala抑制、F-1,6-BP前馈激活"], "check": null, "cards": null}, {"i": 19, "sec": "糖代谢(二)", "title": "PFK的别构调控 (p23-p24) (p20)", "notes": "", "page": 20, "level": "PFK特点：四聚体,每亚基319aa。\u000b具有ATP结合位点和F-6-P结合位点及效应物位点。\u000bF-6-P浓度vs PFK活性曲线：F-2,6-BP显著提高PFK对F-6-P的亲和力→曲线向左移→大大解除ATP/柠檬酸的抑制。\u000bF-2,6-BP由PFK-2合成→受胰高血糖素/胰岛素调控。\u000b这是酵解调控的核心枢纽!", "img": "assets/img/sugar2/p020.jpg", "anim": null, "fig": "", "points": ["①PFK-1是酵解最重要的别构调控酶", "②F-2,6-BP是最强激活剂，ATP/柠檬酸/H⁺为抑制剂"], "check": null, "cards": null}, {"i": 20, "sec": "糖代谢(二)", "title": "TCA环的调节 (p25)", "notes": "二、TCA环的调节。\u000b三大调控点对应三个不可逆酶：(1)柠檬酸合酶→受OAA浓度影响最大→反馈控。\u000b★(2)异柠檬酸脱氢酶→ADP激活,NADH/ATP抑制(最重要)。\u000b(3)α-KG脱氢酶→与PDH类似调控分子(NADH/ATP抑制,Ca2+激活)。\u000b底物和产物的浓度调节确保了TCA速率与ATP需求一致。", "page": 25, "level": "掌握", "img": "assets/img/sugar2/p025.jpg", "anim": null, "fig": "", "points": ["①TCA三个不可逆酶为调控点：柠檬酸合酶、异柠檬酸脱氢酶、α-KG脱氢酶", "②异柠檬酸脱氢酶最重要，ADP激活、NADH/ATP抑制", "③柠檬酸合酶受OAA浓度影响最大", "④α-KG脱氢酶受NADH/ATP抑制、Ca²⁺激活"], "check": null, "cards": null}, {"i": 21, "sec": "糖代谢(二)", "title": "能荷与质量作用比 (p26)", "notes": "三、三大途径协调调节。\u000b能荷(energy charge)=([ATP]+0.5[ADP])/([ATP]+[ADP]+[AMP])。\u000b能荷大→三者皆减慢(产能充分)；\u000b能荷小→三者皆加快(需要产能)。\u000bATP系统质量作用比=[ATP]/[ADP][Pi]→反映氧化磷酸化速率。\u000bNAD+/NADH比也参与呼吸链反馈调节。", "page": 26, "level": "理解", "img": "assets/img/sugar2/p026.jpg", "anim": null, "fig": "", "points": ["①能荷=([ATP]+0.5[ADP])/([ATP]+[ADP]+[AMP])", "②能荷高→三途径减慢；能荷低→三途径加快", "③质量作用比[ATP]/[ADP][Pi]反映氧化磷酸化速率", "④NAD⁺/NADH比参与呼吸链反馈调节"], "check": null, "cards": null}], "mcq": [{"id": "sugar2_mcq_1", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖原合成中,活化的葡萄糖供体是什么?", "o": ["A. G-1-P", "B. UDP-葡萄糖(UDPG)", "C. G-6-P", "D. ADP-葡萄糖"], "a": "B", "e": "UDPG(尿苷二磷酸葡萄糖)是动物糖原合成的活性Glc供体。PPP水解→不可逆!", "kp": "sugar2_s0_2"}, {"id": "sugar2_mcq_2", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖原合酶的功能是什么?", "o": ["A. 水解α-1,4糖苷键", "B. 形成α-1,4糖苷键延伸", "C. 形成α-1,6分支键", "D. 活化葡萄糖"], "a": "B", "e": "糖原合酶催化UDPG+引物→α-1,4键延伸。磷酸化后失活→受胰岛素去磷酸化激活。", "kp": "sugar2_s0_3"}, {"id": "sugar2_mcq_3", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "分支酶如何处理糖原合成中的α-1,6键?", "o": ["A. 直接连接Glc到OH-6", "B. 切断6-7个G残基段+转移到OH-6", "C. 水解α-1,6键", "D. 不需要分支酶"], "a": "B", "e": "分支酶切下6-7个Glc的α-1,4段→转移至OH-6→形成α-1,6分支。增加分支→增溶解性+增非还原端数!", "kp": "sugar2_s0_4"}, {"id": "sugar2_mcq_4", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "植物淀粉合成使用的活化Glc载体是什么?", "o": ["A. UDPG", "B. ADPG(腺苷二磷酸葡萄糖)", "C. G-1-P", "D. CDPG"], "a": "B", "e": "植物淀粉合成→ADPG;动物糖原→UDPG。两种不同的核苷酸糖载体,体现进化差异。", "kp": "sugar2_s0_5"}, {"id": "sugar2_mcq_5", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "蔗糖合成的主要途径是什么?", "o": ["A. UDPG+F→蔗糖+UDP", "B. UDPG+F-6-P→6-磷酸蔗糖→蔗糖+Pi", "C. G+F→蔗糖", "D. G-1-P+F→蔗糖"], "a": "B", "e": "主途:UDPG+F-6-P→磷酸蔗糖合酶→6-磷酸蔗糖→6-P蔗糖磷酸酶+Pi→蔗糖。磷酸蔗糖合酶是主要调控酶。", "kp": "sugar2_s0_8"}, {"id": "sugar2_mcq_6", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖异生(Gluconeogenesis)的定义是什么?", "o": ["A. G→丙酮酸", "B. 非糖物质→葡萄糖/糖原", "C. 糖原→G-1-P", "D. G→G-6-P"], "a": "B", "e": "糖异生=丙酮酸/乳酸/甘油/生糖aa等→Glc或糖原。基本为EMP逆过程(需绕过3个不可逆步→消耗6-7个~P)。", "kp": "sugar2_s0_9"}, {"id": "sugar2_mcq_7", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖异生绕过酵解中哪个酶的步骤需要两次反应?", "o": ["A. 己糖激酶", "B. PFK", "C. 丙酮酸激酶(PK)→需两酶绕行", "D. 醛缩酶"], "a": "C", "e": "绕过PK需两步:①丙酮酸→OAA(丙酮酸羧化酶,线粒体,生物素);②OAA→PEP(PEPCK,胞质)。总需1ATP+1GTP。", "kp": "sugar2_s0_13"}], "judge": [], "fill": [{"id": "sugar2_fill_1", "modI": 0, "q": "糖原合成中,葡萄糖被活化为________,它是________(核苷酸)的高能衍生物。", "a": "UDPG(尿苷二磷酸葡萄糖),UTP", "kp": "sugar2_s0_2"}, {"id": "sugar2_fill_2", "modI": 0, "q": "糖原合酶催化________键的形成,分支酶催化________键的形成。", "a": "α-1,4,α-1,6", "kp": "sugar2_s0_3"}, {"id": "sugar2_fill_3", "modI": 0, "q": "糖异生绕过酵解中三个不可逆反应分别需要________(跳过丙酮酸激酶)、________(跳过PFK-1)和________(跳过己糖激酶)。", "a": "丙酮酸羧化酶+PEPCK,果糖二磷酸酶(FBPase-1),葡萄糖-6-磷酸酶(G-6-Pase)", "kp": "sugar2_s0_12"}, {"id": "sugar2_fill_9", "modI": 0, "q": "植物淀粉合成采用________作为活化Glc载体,与动物UDPG不同;直链淀粉合成采用________支链淀粉需________酶形成α-1,6分支。", "a": "ADPG(腺苷二磷酸葡萄糖),ADPG,Q", "kp": "sugar2_s0_5"}], "short": [{"id": "sugar2_short_1", "modI": 0, "q": "简述糖原合成的全过程(葡萄糖活化、主链延伸和分支形成)。", "a": "糖原合成共三阶段:\u000b\u000b①葡萄糖活化:G→己糖激酶→G-6-P→变位酶→G-1-P+UTP→UDPG焦磷酸化酶→UDPG+PPi(Pi焦磷酸酶→2Pi→不可逆!)\u000b\u000b②α-1,4主链延伸:UDPG+引物(糖原引物蛋白携带)→糖原合酶→α-1,4键延伸+UDP→重复循环→线性链增长→仅从非还原端延伸\u000b\u000b③α-1,6分支形成:分支酶→切下6-7个Glc的α-1,4段→转移到OH-6→形成α-1,6分支→多分支+多非还原端→利于快速动员\u000b\u000b糖原合酶受胰岛素去磷酸化激活→进食后促进糖原储存", "kp": "sugar2_s0_2"}], "calc": [{"id": "sugar2_calc_1", "modI": 0, "q": "计算1分子乳酸在肝中经糖异生生成葡萄糖消耗多少高能磷酸键？净消耗多少？", "a": "净消耗约4~P", "steps": "①2乳酸→2丙酮酸(LDH):0个~P(NADH再氧化,不耗能)\u000b②2丙酮酸→2OAA(丙酮酸羧化酶):2×1ATP=2~P\u000b③2OAA→2PEP(PEPCK):2×1GTP=2~P\u000b④2PEP→...→F-1,6-BP:需1ATP=1~P\u000b⑤F-1,6-BP→F-6-P(FBPase-1):0~P\u000b⑥G-6-P→G(G-6-Pase):0高能键\u000b\u000b总计:2+2+1=5~P\u000b但乳酸→丙酮酸产生的NADH可被利用(3ATP当量)\u000b\u000b可用计算:5~P-2NADH(≈5ATP)=净约0~P(NADH能量抵消)\u000b实际消耗:4-5~P\u000b\u000b与EMP对比:1G→2乳酸=2ATP→2乳酸→1G消耗~4ATP→净亏~2ATP", "kp": "sugar2_s0_15"}, {"id": "sugar2_calc_4", "modI": 0, "q": "计算1分子生糖氨基酸(Ala)经糖异生生成葡萄糖后,在肌肉中酵解为乳酸→再回肝脏糖异生→共消耗多少ATP？", "a": "一完整Cori循环净亏损约4ATP;从Ala起始再加-1ATP→净亏5ATP", "steps": "Ala→肝→糖异生→G:\u000b①Ala+α-KG→丙酮酸+Glu(ALT):0~P\u000b②丙酮酸→糖异生→G:消耗6ATP\u000b\u000b肌肉:1G→2乳酸+2ATP\u000b\u000b肝脏:2乳酸+6ATP→1G\u000b\u000bCori循环往返:\u000b肌肉产:2ATP\u000b肝脏耗:6ATP\u000b净亏:4ATP(但肌肉获2ATP→但整个系统净4个~P)\u000b\u000bAla→G→乳酸→G再循环:\u000b1.Ala→G:6ATP消耗\u000b2.肌肉得G→2ATP产\u000b3.乳酸→G:6ATP消耗\u000b\u000b持续循环总消耗:12-2=10ATP/每最终血中G\u000b但提供G→肌肉→消耗氧化→总保持10代谢代价得到2ATP\u000b极高代价→Cori循环主要发生在紧急/运动→非正常生理状态", "kp": "sugar2_s0_9"}], "term": [{"id": "sugar2_term_1", "modI": 0, "term": "UDPG(尿苷二磷酸葡萄糖)", "def": "①UDPG=尿苷二磷酸葡萄糖→动物糖原合成的活化葡萄糖载体（定义）。②合成:G-1-P+UTP→UDPG+PPi(UDPG焦磷酸化酶→PPi+H2O→无机焦磷酸酶→2Pi→不可逆!)（合成+能源）。③功能:作为高能葡萄糖基供体→糖原合酶→每步加一个Glc残基+释放UDP（功能）。④与G-1-P不同:G-1-P含磷酸基团但非高能→UDPG的糖苷键能量高→足以推动糖原延伸（与G-1-P的区别）。⑤与ADPG、CDPG等相似→植物使用ADPG为淀粉合成活化载体（植物差异）。", "kps": "①定义(1分)②合成反应+焦磷酸酶(1分)③高能糖基载体(1分)④与G-1-P区别(1分)⑤植物ADPG(1分)", "kp": "sugar2_s0_2"}, {"id": "sugar2_term_2", "modI": 0, "term": "糖原合酶(Glycogen Synthase)", "def": "①催化UDPG中Glc残基转移至引物(糖原引物蛋白)的非还原端→形成α-1,4糖苷键的酶（定义+反应）。②仅从非还原端延伸→不可逆且单向（方向）。③引物需要糖原引物蛋白(Glycogenin)提供起始糖基→早期糖原合成在此蛋白上完成（引物）。④受磷酸化调控:胰岛素→蛋白磷酸酶-1→去磷酸化→合酶激活=糖原合成↑;肾上腺素→PKA→磷酸化→合酶失活=合成↓（调控）。⑤与动物UDPG/植物ADPG关系的不同（植物差异）。", "kps": "①定义+反应(1分)②单向延伸(1分)③引物蛋白(1分)④磷酸化调控(2分)⑤与植物对比(1分)", "kp": "sugar2_s0_3"}, {"id": "sugar2_term_3", "modI": 0, "term": "分支酶(Branching Enzyme)", "def": "①糖原合成中催化α-1,6分支键形成的酶（定义）。②过程:切下一段6~7个Glc的α-1,4线性链→将这段转移到同链或邻链的Glc-OH-6→形成α-1,6分支键（机制）。③意义:增加糖原溶解度(非螺旋无定形→不沉淀)→增加非还原端数目(多分支→多点酶切→快速释放Glc)（双重意义）。④与Q酶不同:分支酶处理糖原(每8-12分支)而Q酶处理支链淀粉(每25-30分支)（区别）。⑤缺陷可导致糖原结构异常→糖原贮积病（临床）。", "kps": "①定义(1分)②切断6-7段+转移(1分)③双重意义(1分)④与Q酶区别(1分)⑤临床意义(1分)", "kp": "sugar2_s0_4"}, {"id": "sugar2_term_4", "modI": 0, "term": "ADPG(腺苷二磷酸葡萄糖)", "def": "①ADPG=腺苷二磷酸葡萄糖→植物淀粉合成的活化葡萄糖载体（定义）。②合成:G-1-P+ATP→ADPG+PPi→焦磷酸酶水解(Pi)使反应不可逆（合成）。③功能:作为高能葡萄糖基供体→淀粉合酶→在非还原端或还原端加入Glc→双向延伸(与糖原仅单向不同)（功能+特征）。④与UDPG不同:核苷酸载体不同(UDPG vs ADPG)→植物/动物取不同的核苷酸载体（进化差异）。⑤ADPG焦磷酸化酶是淀粉合成限速酶→受代谢调控（调控）。", "kps": "①定义(1分)②合成反应(1分)③双向延伸(1分)④与UDPG核苷酸差异(1分)⑤调控(1分)", "kp": "sugar2_s0_2"}, {"id": "sugar2_term_16", "modI": 0, "term": "Von Gierke病(糖原贮积病I型)", "def": "①G-6-Pase缺陷导致的最常见的糖原贮积病(常染色体隐性)（定义）。②机制:G-6-Pase缺失→A)不能将G-6-P→G→肝糖原积累; B)低血糖(不能释G); C)代偿性EMP↑→乳酸/乳酸酸中毒（生化）。③积累→肝脾肿大→→肾病风险↑→→生长矮小（临床表现）。④禁食试验:空腹→血糖不降→反而乳酸↑→此病典型特征（诊断）。⑤治疗:频繁多次进食(每2-3小时一餐高淀粉量)+鼻胃夜间持续补充G→限制EMP→延缓并发症（治疗）。", "kps": "①G-6-Pase缺陷(1分)②低血糖+乳酸+糖原累积(1分)③肝肿大+矮小(1分)④实验室特征(1分)⑤治疗原则(1分)", "kp": "sugar2_s0_3"}]}, {"i": 1, "name": "模块二：血糖调节与糖代谢紊乱", "slides": [{"i": 0, "sec": "糖代谢(二)", "title": "血糖物理化学机制 (p27)", "notes": "四、激素对糖代谢调节。\u000b(一)物理/化学机制：血糖<正常值(70-100mg%即3.9-6.1mmol/L)→肝糖元分解↑(磷解酶激活)糖异生↑。\u000b血糖>正常值→肝/肌糖原合成↑。\u000b血糖>160-180mg%(肾糖阈)→尿糖排出(糖尿)。", "page": 27, "level": "掌握", "img": "assets/img/sugar2/p027.jpg", "anim": null, "fig": "", "points": ["①血糖正常值70-100mg%（3.9-6.1mmol/L）", "②低血糖→肝糖原分解↑、糖异生↑", "③高血糖→肝/肌糖原合成↑", "④超过肾糖阈160-180mg%出现糖尿"], "check": null, "cards": null}, {"i": 1, "sec": "糖代谢(二)", "title": "升糖激素-Ad/胰高血糖素 (p28)", "notes": "(二)升糖激素机制：低血糖→Ad(肾上腺素)/GL(胰高血糖素)分泌→与细胞膜G蛋白偶联受体结合→腺苷酸环化酶(AC)活性↑→cAMP↑→激活PKA→磷酸化:糖原磷酸化酶(激活)→糖原分解↑。\u000bPEPCK/FBPase-2→转录诱导→糖异生↑。\u000b级联放大:1分子Ad→百万级G→快速升糖!", "page": 28, "level": "掌握", "img": "assets/img/sugar2/p028.jpg", "anim": null, "fig": "", "points": ["①升糖激素为肾上腺素和胰高血糖素", "②经G蛋白偶联受体→AC↑→cAMP↑→PKA激活", "③PKA磷酸化激活糖原磷酸化酶→糖原分解↑", "④诱导PEPCK/FBPase-2转录→糖异生↑，级联放大快速升糖"], "check": null, "cards": null}, {"i": 2, "sec": "糖代谢(二)", "title": "降糖激素-胰岛素 (p29)", "notes": "(二)降糖激素机制：高血糖→胰岛素(Ins)分泌→与细胞膜胰岛素受体结合→激活受体酪氨酸激酶→多条信号通路:(1)激活蛋白磷酸酶-1→去磷酸化→抑制磷酸化酶(糖原分解↓)+激活糖原合酶(合成↑)。\u000b(2)激活PKB→促进GLUT4膜转位→加速糖摄入。\u000b降低血糖。", "page": 29, "level": "掌握", "img": "assets/img/sugar2/p029.jpg", "anim": null, "fig": "", "points": ["①高血糖刺激胰岛素分泌，与膜受体结合", "②受体酪氨酸激酶激活，启动多条信号通路", "③蛋白磷酸酶-1去磷酸化：抑糖原分解、促合成", "④PKB促GLUT4转位，加速葡萄糖摄取降糖"], "check": null, "cards": null}, {"i": 3, "sec": "糖代谢(二)", "title": "血糖来源与去路 (p30)", "notes": "血糖(70-100mg%)的动态平衡：来源→食物消化吸收+肝糖元分解+糖异生(非糖物质);去路→各组织氧化供能+肝/肌糖元合成+转变为脂肪/AA等。\u000b当血糖>肾糖阈(160-180mg%)→尿糖排出。\u000b血糖稳态需要多种组织/激素/酶协同调控!", "page": 30, "level": "掌握", "img": "assets/img/sugar2/p030.jpg", "anim": null, "fig": "", "points": ["①血糖正常值70-100mg%，处于动态平衡", "②来源：食物吸收、肝糖原分解、糖异生", "③去路：氧化供能、合成糖原、转变为脂肪/AA", "④超过肾糖阈(160-180mg%)则出现尿糖"], "check": null, "cards": null}, {"i": 4, "sec": "糖代谢(二)", "title": "第七节-糖代谢紊乱 (p31)", "notes": "第七节 糖代谢紊乱。\u000b内容：一、高血糖及糖尿病；\u000b二、低血糖症。\u000b全球约5.89亿成人(20-79岁)患有糖尿病。\u000b中国约1.5亿糖尿病患者居全球首位。\u000b从生化机制理解血糖失衡的分子基础。", "page": 31, "level": "掌握", "img": "assets/img/sugar2/p031.jpg", "anim": null, "fig": "", "points": ["①本节讲糖代谢紊乱：高血糖/糖尿病与低血糖症", "②全球约5.89亿成人患糖尿病", "③中国约1.5亿患者，居全球首位", "④从生化机制理解血糖失衡的分子基础"], "check": null, "cards": null}, {"i": 5, "sec": "糖代谢(二)", "title": "高血糖及糖尿病 (p32-p33) (p6)", "notes": "一、高血糖及糖尿病。\u000b空腹血糖>100mg%(6.1mmol/L)=高血糖。\u000b空腹血糖>160-180mg%(8.9-10mmol/L)=糖尿病(肾糖阈超过)。\u000b糖尿病病因：胰岛素缺乏(1型)或其受体异常/抵抗(2型)。\u000b全球大流行:2025年5.89亿人→2050年预计增至8.525亿(增45%)。", "page": 6, "level": "掌握", "img": "assets/img/sugar2/p006.jpg", "anim": null, "fig": "", "points": ["①空腹血糖>100mg%即高血糖", "②>160-180mg%超过肾糖阈为糖尿病", "③1型为胰岛素缺乏，2型为受体异常/抵抗", "④全球糖尿病患病率快速上升，2050年预计8.525亿"], "check": null, "cards": null}, {"i": 6, "sec": "糖代谢(二)", "title": "糖尿病生化机制 (p34)", "notes": "糖尿病起因=胰岛素缺乏/受体障碍→细胞无法充分利用G。\u000b分子后果：糖原合成↓(合酶不能激活)→G氧化分解↓(EMP/TCA↓)→糖异生↑(肝释放更多G)→血G↑。\u000b过量乙酰CoA积累→酮体↑(酮血症/酮尿症)→酸中毒。\u000b并发症：血管病变/视网膜损伤→发展为肾病/四肢坏疽/心肌症等。", "page": 34, "level": "掌握", "img": "assets/img/sugar2/p034.jpg", "anim": null, "fig": "", "points": ["①胰岛素缺乏/受体障碍致细胞不能利用葡萄糖", "②糖原合成↓、氧化分解↓、糖异生↑→血糖↑", "③乙酰CoA堆积→酮体↑→酮血症、酸中毒", "④并发症：血管病变、视网膜损伤、肾病、坏疽"], "check": null, "cards": null}, {"i": 7, "sec": "糖代谢(二)", "title": "低血糖症 (p35)", "notes": "二、低血糖症。\u000b血糖<60-70mg%为低血糖;<45mg%出现脑功能障碍→头痛、昏迷。\u000b起因:激素调节紊乱→①胰岛素分泌过量(胰岛素瘤);②垂体/肾上腺皮质机能减退→糖皮质激素分泌下降→Gluconeogenesis↓(抑制肝糖释放);糖皮质激素正常的生理作用=促进糖异生+减少组织G利用→维持血糖。", "page": 35, "level": "掌握", "img": "assets/img/sugar2/p035.jpg", "anim": null, "fig": "", "points": ["①血糖<60-70mg%为低血糖，<45mg%致脑功能障碍", "②胰岛素瘤致胰岛素分泌过量", "③垂体/肾上腺皮质机能减退→糖皮质激素↓", "④糖皮质激素促糖异生、减少组织利用糖以维持血糖"], "check": null, "cards": null}], "mcq": [{"id": "sugar2_mcq_8", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "糖异生的关键限速酶之一FBPase-1受何种物质抑制?", "o": ["A. ATP", "B. AMP和F-2,6-BP", "C. NADH", "D. 乙酰CoA"], "a": "B", "e": "FBPase-1受AMP和F-2,6-BP抑制,与PFK-1恰好相反(AMP/2,6-BP激活PFK)。保证EMP或糖异生单向运行!", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_9", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "G-6-Pase(葡萄糖-6-磷酸酶)存在于哪个组织?", "o": ["A. 所有组织", "B. 肝和肾(肌肉无)", "C. 仅肌肉", "D. 仅脑"], "a": "B", "e": "G-6-Pase仅在肝/肾内质网→水解G-6-P→G+Pi→释G入血。肌肉无→肌糖原不能释放G直接供血→只能利己用。", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_10", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "1分子G经EMP产2ATP,而糖异生产1G消耗多少高能磷酸键?", "o": ["A. 2ATP", "B. 4-5~P(4ATP+2GTP=约7高能键)", "C. 6-7~P(净亏4-5)", "D. 8-10~P"], "a": "C", "e": "糖异生:4ATP+2GTP=含7个高能磷酸键(2GTP中的~P计为2个~键)。EMP产2ATP→净亏4-5个~P。高能耗保证代谢高效单向性。", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_11", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "作为糖异生前体,乳酸来自哪个循环?", "o": ["A. 葡萄糖-丙氨酸循环", "B. Cori循环(乳酸循环)", "C. TCA循环", "D. PPP"], "a": "B", "e": "Cori循环:肌肉乳酸→血→肝→乳酸→糖异生→G→肌肉。乳酸是糖异生主要前体(激烈运动后明显)。", "kp": "sugar2_s1_0"}, {"id": "sugar2_mcq_12", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "酵解中的最重要调控酶是什么?", "o": ["A. 己糖激酶", "B. PFK-1(磷酸果糖激酶)★", "C. GAPDH", "D. PK"], "a": "B", "e": "PFK-1是EMP最重要调控点→被ATP/H+/柠檬酸抑制;被AMP/ADP/F-2,6-BP激活。别构调控的教科书级别酶!", "kp": "sugar2_s1_3"}, {"id": "sugar2_mcq_13", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "F-2,6-BP对PFK-1的作用是什么?", "o": ["A. 竞争性抑制", "B. 增强F-6-P亲和力→克服ATP/柠檬酸抑制", "C. 促进PFK-1降解", "D. 作为底物"], "a": "B", "e": "F-2,6-BP使PFK活性vsF-6-P浓度曲线左移→大大提高亲和力→解除ATP/柠檬酸抑制。最强别构激活剂!", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_14", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "TCA环最重要的调控酶是什么?", "o": ["A. 柠檬酸合酶", "B. 异柠檬酸脱氢酶★", "C. a-KG脱氢酶", "D. 琥珀酸脱氢酶"], "a": "B", "e": "异柠檬酸脱氢酶→受ADP激活(低能荷信号),NADH/ATP抑制(高能荷信号)。是TCA最重要的调控点→反映细胞能量状态。", "kp": "sugar2_s1_6"}, {"id": "sugar2_mcq_15", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "能荷(energy charge)反映什么?", "o": ["A. 细胞内CO2浓度", "B. 胞内ATP/ADP/AMP相对含量", "C. 血糖浓度", "D. NAD+/NADH比"], "a": "B", "e": "能荷=([ATP]+0.5[ADP])/([ATP]+[ADP]+[AMP])。能荷大→产能途径减慢;能荷小→产能加速。0~1之间,正常约0.85-0.90。", "kp": "sugar2_s1_7"}], "judge": [], "fill": [{"id": "sugar2_fill_4", "modI": 1, "q": "酵解最重要的调控酶是________,它被________(促进因子)激活,被________和________(抑制因子)抑制。", "a": "磷酸果糖激酶(PFK-1),AMP/F-2,6-BP,ATP,柠檬酸", "kp": "sugar2_s1_2"}, {"id": "sugar2_fill_6", "modI": 1, "q": "正常空腹血糖浓度为________mg%即________mmol/L。肾糖阈为________mg%。", "a": "70-100,3.9-6.1,160-180", "kp": "sugar2_s1_0"}, {"id": "sugar2_fill_7", "modI": 1, "q": "升糖激素主要为________和________,两者通过________信号通路触发糖原分解。", "a": "肾上腺素(Ad),胰高血糖素(GL),cAMP-PKA级联放大", "kp": "sugar2_s1_1"}, {"id": "sugar2_fill_8", "modI": 1, "q": "Cori循环中,肌肉酵解产生________,经血液运至________,经________途径生成葡萄糖回到肌肉。", "a": "乳酸,肝脏,糖异生", "kp": "sugar2_s1_6"}, {"id": "sugar2_fill_10", "modI": 1, "q": "1分子葡萄糖经酵解净产________ATP,而2分子丙酮酸经糖异生合成1分子葡萄糖消耗约________ATP,净亏约________ATP以保证代谢双向性。", "a": "2,6-7,4-5", "kp": "sugar2_s1_4"}], "short": [{"id": "sugar2_short_2", "modI": 1, "q": "简述糖异生绕过EMP三个不可逆步骤的机制和关键酶。", "a": "糖异生基本是EMP逆过程→但三步不可逆必须绕过:\u000b\u000b绕过PK(PEP→丙酮酸):需两步反应\u000b①线粒体:丙酮酸+CO2+ATP→丙酮酸羧化酶(生物素辅基)→OAA+ADP+Pi\u000b②胞质:OAA→苹果酸→出线粒体→OAA+GTP→PEPCK→PEP+CO2+GDP\u000b共需:1ATP+1GTP\u000b\u000b绕过PFK-1:F-1,6-BP+H2O→FBPase-1→F-6-P+Pi(受AMP/F-2,6-BP抑制)\u000b\u000b绕过己糖激酶:G-6-P+H2O→G-6-Pase(内质网,肝/肾特有)→G+Pi→释放入血\u000b\u000b总消耗:4ATP+2GTP(~7个~P)→等价4-5ATP→代谢高效单向性", "kp": "sugar2_s1_6"}, {"id": "sugar2_short_4", "modI": 1, "q": "比较升糖激素(Ad/GL)和降糖激素(胰岛素)对糖代谢的调控机理。", "a": "升糖激素(Ad/GL)—cAMP-PKA级联:\u000b①激素→与G蛋白受体结合→腺苷酸环化酶→cAMP↑\u000b②cAMP→PKA→磷酸化靶蛋白:\u000b• 糖原磷酸化酶→磷酸化→活化→糖原→G-1-P→G进入血\u000b• 糖原合酶→磷酸化→失活→糖原合成↓\u000b• PEPCK/FBPase-1→转录诱导→糖异生↑\u000b③级联放大:1激素分子→百万G→快速升糖\u000b\u000b降糖激素(胰岛素)—Tyr激酶→磷酸酶:\u000b①Ins→受体Tyr激酶→多条信号通路\u000b②蛋白磷酸酶-1→去磷酸化:\u000b• 磷酸化酶→去磷酸→失活→糖原分解↓\u000b• 糖原合酶→去磷酸→激活→糖原合成↑\u000b③PKB→GLUT4膜转位→G摄入↑\u000b④EMP酶→转录诱导→G氧化↑\u000b\u000b净效果:Ad/GL→血糖↑;胰岛素→血糖↓→两者拮抗维持血糖稳态", "kp": "sugar2_s1_2"}, {"id": "sugar2_short_5", "modI": 1, "q": "简述血糖的来源、去路及稳态调控机制。", "a": "血糖正常范围:70-100mg%(3.9-6.1mmol/L)。\u000b\u000b血糖来源(输入):\u000b①食物消化吸收→G→小肠→门静脉→肝\u000b②肝糖原分解→G(肝G-6-Pase)→释放入血\u000b③糖异生→乳酸/甘油/生糖aa→G(肝/肾)→入血\u000b\u000b血糖去路(输出):\u000b①各组织氧化→EMP→TCA→CO2+H2O+大量ATP\u000b②肝/肌糖原合成→储存\u000b③转化为脂肪→脂肪酸合成\u000b④>肾糖阈(160-180mg%)→尿糖排出\u000b\u000b激素调控:\u000b• 低血糖(<70-100)→Ad/GL↑→cAMP→糖原分解+糖异生↑\u000b• 高血糖(>120-150)→Ins↑→氧化↑+合成↑+摄入↑\u000b• 应激→Ad↑→快速动员糖原供战\u000b植物无此激素系统→代谢调控靠非激素微调", "kp": "sugar2_s1_3"}, {"id": "sugar2_short_7", "modI": 1, "q": "简述糖尿病两类分型的生化机制差异。", "a": "糖尿病基本机制:胰岛素信号通路障碍→细胞G利用↓→血G↑。\u000b\u000b1型糖尿病(T1D):\u000b• 病因:胰岛β细胞被自身免疫攻击→绝对胰岛素缺乏\u000b• 发病:幼儿/青少年期→急\u000b• 机制:无Ins→无法激活糖原合成/EMP/脂肪合成↓→所有代谢退化\u000b• 治疗:必须外源补给胰岛素(注射)→依靠注入Ins+监测血糖\u000b\u000b2型糖尿病(T2D):\u000b• 病因:胰岛素血中存在但细胞受体异常→胰岛素抵抗\u000b• 发病:中老年→渐进,与生活方式相关(更多)\u000b• 机制:受体后缺陷→如GLUT4不能膜转位→细胞摄入G能力↓\u000b  →高G刺激胰B细胞→高Ins环境→长期→β细胞衰减→最终可有胰岛素缺发\u000b• 治疗:非药→生活方式干预;药→提高Ins敏感性\u000b\u000b相同后果:两大类型均导致:\u000b• G氧化↓→脂肪替代产能→酮体↑→酸中毒\u000b• 长期高血糖→蛋白质糖基化→血管病变、肾病等并发症", "kp": "sugar2_s1_6"}], "calc": [{"id": "sugar2_calc_2", "modI": 1, "q": "计算1分子葡萄糖-6-磷酸进入糖原合成最终储存为糖原,消耗几个高能磷酸键？与G→糖原相比有何区别？", "a": "仅1个~P(G→G-6-P需1ATP,糖原储存不需另外的~P),比G→糖原更节省能量", "steps": "G-6-P→糖原:\u000b①G-6-P→G-1-P(变位酶):0~P\u000b②G-1-P+UTP→UDPG+PPi:0~P(PPi水解推动→等价消耗1~P)\u000b③UDPG+引物→糖原合酶→糖原+UDP:0~P\u000b\u000bUDP相当于已活化→一次UDP代表已付1个~P\u000b\u000b若从G开始:\u000b①G→G-6-P:1ATP(1~P)\u000b②G-6-P→G-1-P:0~P\u000b③G-1-P+UTP→UDPG:等价1~P\u000b④糖原储存:0~P\u000b\u000b总计:2~P(从G→糖原储存一个Glc残留)\u000b\u000b而G-6-P直接进糖原储存仅需1~P(UTP生成步)\u000b→G-6-P→糖原比G→糖原节省1个~P", "kp": "sugar2_s1_1"}, {"id": "sugar2_calc_3", "modI": 1, "q": "论述Cori循环(乳酸循环)的完整过程及能量平衡,计算1分子葡萄糖经Cori循环两次往返后的总消耗。", "a": "两次Cori往返净亏损28ATP", "steps": "Cori循环一次往返:\u000b肌肉:1G→2乳酸+2ATP(酵解产)+2NADH(c)\u000b肝脏:2乳酸+6ATP→1G(糖异生消耗)\u000b\u000b能量平衡:\u000b肌肉产:2ATP\u000b肝脏耗:6ATP\u000b净亏:4ATP/一往返(肌肉获得的ATP代价4倍)\u000b但2NADH(c)产的ATP(5或3)在其他组织中利用\u000b\u000b两次往返:\u000b含两个细胞的各两次循环,总消耗=\u000b双细胞×2(酵解-糖异生)往返=4(耗4ATP×2次×1分子=4ATP?错了)\u000b\u000b正确:2分子G→2次酵解=4ATP生成\u000b2次糖异生=12ATP消耗\u000b净亏:8ATP(不计NADH促进的额外ATP)\u000b加上NADH进入呼吸链的差值:\u000b2次糖异生需2×2NADH=4NADH→可选进行→减少净亏损\u000b实际净亏:约28ATP(两往返)×? 实际:\u000b\u000b一往返亏损4(纯细胞ATP)+两NADH价值=5→净盈余1~ATP\u000b或甘油-3-P穿梭→两循环亏损4×3=12-乳酸→糖异生再耗多\u000b\u000b说明Cori循环是紧急供能,能量代价巨大但能保障脑/心获得所需G", "kp": "sugar2_s1_1"}, {"id": "sugar2_calc_5", "modI": 1, "q": "论述PFK-1同时被ATP别构抑制和F-2,6-BP别构激活的整合调控机制。", "a": "PFK-1是EMP的核心调控枢纽,整合多信号决定EMP速率", "steps": "PFK-1是EMP的核心调控枢纽,整合多信号决定EMP速率", "kp": "sugar2_s1_0"}], "term": [{"id": "sugar2_term_5", "modI": 1, "term": "糖异生(Gluconeogenesis)", "def": "①非糖物质(丙酮酸/乳酸/甘油/生糖氨基酸)转化生成葡萄糖或糖原的过程（定义）。②部位:肝脏(主要)+肾脏皮质（部位）。③需绕过EMP 3个不可逆步:丙酮酸→OAA(丙酮酸羧化酶+生物素)→PEP(PEPCK)→绕过PK;F-1,6-BP→F-6-P(FBPase-1)→绕过PFK;G-6-P→G(G-6-Pase)→绕过HK（绕道机制）。④能量:2丙酮酸→1G消耗4ATP+2GTP=约6-7~P→净亏4-5~P→保证代谢单向性（能耗）。⑤意义:维持血糖→供应脑组织(>100gG/日)→紧急供能→回收乳酸等废物回收（意义）。", "kps": "①定义(1分)②肝/肾(1分)③绕过三步(2分)④能耗(1分)⑤多种意义(1分)", "kp": "sugar2_s1_7"}, {"id": "sugar2_term_6", "modI": 1, "term": "丙酮酸羧化酶(Pyruvate Carboxylase, PC)", "def": "①催化丙酮酸+CO2+ATP→草酰乙酸(OAA)+ADP+Pi→不可逆→糖异生起始酶（定义+反应）。②部位:线粒体基质→草酰乙酸生成处→OAA→苹果酸→穿出线粒体→胞质（部位+通路）。③辅基:生物素(Biotin=A维生素B7)→共价结合Lys→捕获CO2并转移至丙酮酸以获得羧基（辅基）。④调控:受乙酰CoA别构激活(储脂→β-氧化→乙酰CoA↑→糖异生↑→应对能量需求)（调控）。⑤缺陷→低血糖+乳酸性酸中毒+神经系统损伤→婴儿危症（临床）。", "kps": "①反应式(1分)②线粒体(1分)③生物素辅基(1分)④乙酰CoA激活(1分)⑤临床缺陷(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_7", "modI": 1, "term": "PEPCK(磷酸烯醇式丙酮酸羧激酶)", "def": "①糖异生第二步绕道→催化OAA+GTP(或GDP)→PEP+CO2+GDP(或GTP)→不可逆的脱羧反应（定义+反应）。②位于胞质或线粒体(不同物种)（部位）。③消耗1GTP高能磷酸键→驱动脱羧→使OAA转变回PEP→完成绕过PK（能耗）。④PEPCK表达受糖皮质激素诱导(饥饿)→增加糖异生→促进肝糖输出→维持血糖（调控）。⑤与PC协同:PC提供OAA→PEPCK转化为PEP→回入EMP逆向步骤（与PC的关系）。", "kps": "①定义+反应(1分)②胞质位点(1分)③GTP消耗(1分)④激素调控(1分)⑤与PC协同(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_8", "modI": 1, "term": "FBPase-1(果糖-1,6-二磷酸酶-1)", "def": "①糖异生的关键限速酶之一→F-1,6-BP+H2O→F-6-P+Pi→绕过EMP中PFK（定义+反应）。②受AMP强抑制(低能荷)→F-2,6-BP抑制（调节）。③PFK-1与此完全相反:AMP/F-2,6-BP→激活↓→EMP与糖异生的完美对立调控（对应PFK-1的互反关系）。④意义:保证EMP与糖异生不空转→决定代谢通路定向→细胞高效利用底物（意义）。⑤与FBPase-2不同(双功能酶→配EMP/GL激素调控F-2,6-BP浓度)（区分）。", "kps": "①反应(1分)②AMP/F-2,6-BP抑制(1分)③与PFK-1互反(1分)④意义(1分)⑤与FBPase-2区分(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_9", "modI": 1, "term": "G-6-Pase(葡萄糖-6-磷酸酶)", "def": "①G-6-P+H2O→G+Pi在肝/肾内质网膜进行→绕过己糖激酶→糖异生最后一步（定义+反应）。②G-6-Pase定位于内质网→G随后进入血液（部位）。③仅肝和肾存在G-6-Pase→肌肉无→肌肉糖原不能直接释G到循环（组织差异）。④缺陷→Von Gierke病(糖原贮积病I型)→糖原积累+低血糖+乳酸酸中毒（临床）。⑤与己糖激酶的完全逆转关系:己糖激酶→G→G-6-P,  G-6-Pase→G-6-P→G（与己糖激酶的对比）。", "kps": "①反应式(1分)②内质网(1分)③组织差异(1分)④Von Gierke病(1分)⑤与己糖激酶逆转(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_10", "modI": 1, "term": "能荷(Energy Charge)", "def": "①细胞内腺苷酸的高能磷酸状态指标:EC=([ATP]+0.5[ADP])/([ATP]+[ADP]+[AMP])→取值范围0~1（定义+公式）。②高能荷(>0.85):ATP↑→产能途径减慢→合成代谢↑(细胞能量充分)（高能荷状态）。③低能荷(<0.50):AMP↑→产能途径加快→酵解/TCA加速→ATP回补（低能荷状态）。④调控原理:ATP、ADP、AMP相互转化形成三角平衡→任一变化→整个EC变→各代谢途径同时响应→严密协调供能和用能（三角平衡）。⑤正常能荷约0.85-0.90→细胞内精制度量→微调AMP激活的激酶和ATP抑制的调控位点（常态化）。", "kps": "①公式(1分)②高/低能荷状态(1分)③限速酶调控(1分)④三角平衡(1分)⑤正常范围(1分)", "kp": "sugar2_s1_7"}, {"id": "sugar2_term_11", "modI": 1, "term": "PFK-2/FBPase-2(双功能酶)", "def": "①一种兼具两个酶活性的双功能酶→合成/降解F-2,6-BP（定义）。②PFK-2功能:F-6-P+ATP→F-2,6-BP+ADP→F-2,6-BP是PFK-1的最强别构激活剂（合成功能）。③FBPase-2功能:F-2,6-BP+F-6-P→→F-6-P+Pi→降低F-2,6-BP→EMP↓（降级功能）。④磷酸化调控:胰高血糖素→cAMP→PKA→磷酸化→PFK-2活性↓+FBPase-2活性↑→F-2,6-BP↓→EMP↓（饥饿）。胰岛素→去磷酸化→PFK-2↑+FBPase-2↓→F-2,6-BP↑→EMP↑（进食）。⑤一端调控EMP开关→枢纽级位置（意义）。", "kps": "①双功能酶(1分)②PFK-2合成(1分)③FBPase-2降解(1分)④磷酸化调控(1分)⑤EMP开关(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_12", "modI": 1, "term": "Cori循环(乳酸循环)", "def": "①肌肉与肝之间通过乳酸和葡萄糖的相互转化构成的代谢循环（定义）。②过程:肌肉酵解→G→2乳酸(LDH)+2ATP→乳酸→血液→肝脏→乳酸→丙酮酸→糖异生→G→血液→肌肉→再次酵解（过程）。③能量:肌肉产2ATP,肝糖异生消耗6ATP→净亏4ATP/往返（能量）。④生理意义:废物回收(乳酸解毒)→回收C骨架→维持血糖→保障脑/心供能→极重要意义但代价高（意义）。⑤激烈运动后→乳酸↑→血pH↓→Cori循环加速→乳酸性酸中毒可能（运动生理）。", "kps": "①定义(1分)②完整过程(2分)③能量(1分)④意义(1分)⑤运动联系(1分)", "kp": "sugar2_s1_6"}, {"id": "sugar2_term_13", "modI": 1, "term": "胰岛素受体(Insulin Receptor)", "def": "①细胞膜上结合胰岛素的受体→属于受体酪氨酸激酶(RTK)家族（定义）。②亚基结构:α2β2四聚体→两个α亚基(胞外结合Ins)+两个β亚基(胞内Tyr激酶活性)（结构）。③信号:胰岛素结合α→β亚基自磷酸化(Tyr位点)→激活多条通路:PI3K-Akt→GLUT4膜转位→G摄入↑;MAP→转录诱导EMP/TCA酶↑（信号）。④去糖调控:诱导蛋白质磷酸酶-1→去磷酸化→糖原合酶激活+磷酸化酶失活→糖原合成↑（去糖作用）。⑤抵抗→II型糖尿病→受体后缺陷→严重高血糖（临床）。", "kps": "①RTK家族(1分)②α2β2结构(1分)③PI3K-Akt/PKB通路(1分)④去糖调控(1分)⑤抵抗→T2D(1分)", "kp": "sugar2_s1_2"}, {"id": "sugar2_term_14", "modI": 1, "term": "GLUT4转运蛋白", "def": "①肌细胞和脂肪细胞中胰岛素响应的葡萄糖转运蛋白（定义）。②定位:静息时位于胞内膜泡中→胰岛素刺激→PKB信号→运输至细胞膜→G加快跨膜扩散（机制）。③功能:半饱和G浓度~Km≈5mM→很接近空腹血糖水平→高效转运（效率）。④与GLUT1~3不同:GLUT4为胰岛素调节(动态)→其余为组成型(恒态可用)（差异）。⑤胰岛素缺乏/II型糖尿病→GLUT4不能膜移位→细胞G摄入↓→高血糖（临床）。", "kps": "①定义(1分)②胰岛素→膜移位(1分)③Km约5mM(1分)④与GLUT1-3对比(1分)⑤糖尿病(1分)", "kp": "sugar2_s1_2"}, {"id": "sugar2_term_15", "modI": 1, "term": "肾糖阈(Renal Glucose Threshold)", "def": "①血糖浓度160-180mg%(8.9-10mmol/L)时肾小管重吸收G达到最大→超过此值→G出现在尿中→即糖尿（定义）。②机制:肾小球滤过G→近端小管SGLT二钠Glc共转运蛋白→重吸收G→但最大重吸收速率(TmG)有限(mg/min)（机制）。③正常血糖:70-100mg%→TmG远超滤过量→尿无G→超过10mmol/L→超过TmG→尿糖阳性（正常vs糖尿）。④临床:糖尿病患者检测尿G(+)→但尿G(+)不能确定糖尿病(可见于正常妊娠/肾小管功能异常)（临床）。⑤意义:诊断和监测糖尿效果(血糖可随时间变化而尿糖反映最近几小时血糖水平)（意义）。", "kps": "①定义+阈值浓度(1分)②SGLT重吸收机制(1分)③正常尿无G(1分)④糖尿与TMG(1分)⑤临床意义(1分)", "kp": "sugar2_s1_7"}]}, {"i": 2, "name": "模块三：血糖调节·考题练习", "slides": [], "mcq": [{"id": "sugar2_mcq_16", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "升糖激素包括哪些?", "o": ["A. 仅胰岛素", "B. 肾上腺素(Ad)+胰高血糖素(GL)", "C. 仅甲状腺素", "D. 仅生长激素"], "a": "B", "e": "升糖激素:Ad+GL→G蛋白→AC→cAMP→PKA→级联放大→糖原分解↑→快速升糖。肾上腺和胰高血糖素的协同作用。", "kp": null}, {"id": "sugar2_mcq_17", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "胰岛素的降糖机制之一是什么?", "o": ["A. 激活糖原磷酸化酶", "B. 激活蛋白磷酸酶-1→去磷酸化→激活糖原合酶+抑制磷酸化酶", "C. 促进糖异生", "D. 抑制GLUT4"], "a": "B", "e": "胰岛素→受体Tyr激酶→蛋白磷酸酶-1→去磷酸化→糖原合酶激活(合成↑)+磷酸化酶抑制(降解↓)+GLUT4膜转位(摄入↑)→降血糖。", "kp": null}, {"id": "sugar2_mcq_18", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "正常空腹血糖浓度为多少?", "o": ["A. 50-80mg%", "B. 70-100mg%(3.9-6.1mmol/L)", "C. 120-150mg%", "D. 160-180mg%"], "a": "B", "e": "正常空腹血糖=70-100mg%=3.9-6.1mmol/L。>100mg%=高血糖;>160-180mg%=糖尿病(肾糖阈)。<60-70mg%=低血糖。", "kp": null}, {"id": "sugar2_mcq_19", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "肾糖阈是多少?", "o": ["A. 70-100mg%", "B. 160-180mg%", "C. 120-150mg%", "D. 200mg%以上"], "a": "B", "e": "肾糖阈=160-180mg%(8.9-10mmol/L)→超过此浓度→肾小管重吸收能力饱和→尿中排出糖→糖尿。糖尿病患者超过肾糖阈出现糖尿。", "kp": null}, {"id": "sugar2_mcq_20", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "糖尿病导致酮血症的原因是什么?", "o": ["A. 肝脂肪合成↑", "B. 胰岛素缺乏→G氧化↓→过量乙酰CoA→酮体↑→酸中毒", "C. 糖原合成↑", "D. PPP↑"], "a": "B", "e": "胰岛素缺乏→细胞无法充分利用糖→代偿性脂肪分解→脂肪酸β-氧化→大量乙酰CoA积累→HMG-CoA→酮体↑(β-羟基丁酸/乙酰乙酸/丙酮)→代谢性酸中毒!", "kp": null}, {"id": "sugar2_mcq_21", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "低血糖症的临界血糖值是?", "o": ["A. 60-70mg%以下", "B. 80-90mg%", "C. 100-120mg%", "D. 160-180mg%"], "a": "A", "e": "血糖<60-70mg%=低血糖。<45mg%→脑功能障碍→头痛/昏迷(脑主要依赖G供能)。主要因胰岛素过量或皮质激素不足。", "kp": null}, {"id": "sugar2_mcq_22", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "糖皮质激素的生理作用是什么?", "o": ["A. 促进酵解", "B. 促进糖异生+减少组织糖利用→维持血糖", "C. 促进糖原合成", "D. 促进胰岛素分泌"], "a": "B", "e": "糖皮质激素→促进糖异生(诱导PEPCK/FBPase-1)+减少组织糖利用→维持血糖。此机制解释了肾上腺皮质功能减退→低血糖的原因。", "kp": null}], "judge": [], "fill": [{"id": "sugar2_fill_5", "modI": 2, "q": "TCA环最重要的调控酶是________,被________激活,被________抑制。", "a": "异柠檬酸脱氢酶,ADP,NADH/ATP", "kp": null}], "short": [{"id": "sugar2_short_3", "modI": 2, "q": "简述PFK-1的别构调控机制和F-2,6-BP的作用。", "a": "PFK-1是EMP最重要调控酶(四聚体,每亚基319aa):\u000b\u000b抑制因子:\u000b• ATP↑→与别构位点结合→降低F-6-P亲和力→EMP↓(高能荷反馈)\u000b• 柠檬酸↑→增强ATP抑制→EMP↓(TCA产物反馈)\u000b• H+↑→抑制→过量乳酸堆积→自我保护\u000b\u000b激活因子:\u000b• AMP/ADP↑→与ATP竞争别构位点→EMP↑(低能荷信号)\u000b• F-2,6-BP↑→最强激活剂→结合别构位点→显著增加F-6-P亲和力→曲线左移→消除ATP/柠檬酸抑制\u000b• F-2,6-BP由PFK-2合成→受胰岛素(↑)和胰高血糖素(↓)调控\u000b\u000b生理整合:进食后胰岛素↑→F-2,6-BP↑→EMP↑;饥饿时GL↑→F-2,6-BP↓→EMP↓→允许脑有更多G", "kp": null}, {"id": "sugar2_short_6", "modI": 2, "q": "简述TCA环中三个不可逆酶的调控机制。", "a": "TCA三调控点与三个不可逆酶对应:\u000b\u000b①柠檬酸合酶:\u000b• 底物:OAA浓度↑→激活(最重要调节→OAA浓度决定了合酶活性)\u000b• 产物:柠檬酸/NADH/ATP↑→抑制→反馈↓\u000b• 抑制剂:琥珀酰CoA→竞争结合\u000b\u000b②异柠檬酸脱氢酶★(最关键调控点):\u000b• 激活剂:ADP↑(低能荷)→别构激活→TCA↑→产能↑\u000b• 抑制剂:NADH/ATP↑(高能荷)→抑制→TCA↓→节约原料\u000b• Ca2+↑→激活(呼应肌肉收缩、代谢增强等能量需求→TCA加速)\u000b\u000b③α-KG脱氢酶系:\u000b• 与PDH类似→受磷酸化/去磷酸化调控\u000b• NADH/琥珀酰CoA↑→抑制;Ca2+→激活\u000b\u000b总体逻辑:细胞ATP含量调控TCA速率→高ATP时TCA减慢,低ATP时TCA加速→维持能量稳态", "kp": null}], "calc": [], "term": []}, {"i": 3, "name": "模块四：糖合成与糖异生·考题练习", "slides": [], "mcq": [{"id": "sugar2_mcq_23", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "淀粉合成与糖原合成的一个重要区别是什么?", "o": ["A. 完全相同", "B. 淀粉可双向延伸(还原+非还原端),糖原仅单向(非还原端)", "C. 糖原可双向延伸", "D. 都不需要引物"], "a": "B", "e": "淀粉合酶可在非还原端或还原端加入Glc→双向延伸。糖原合酶仅从非还原端延伸→单向。需要引物(小糖原)启动。", "kp": null}, {"id": "sugar2_mcq_24", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "分支酶/糖原Q酶的生理意义?", "o": ["A. 仅提高寡糖甜度", "B. 增加溶解度+增加非还原端数→加快降解/合成速率", "C. 仅有结构作用", "D. 无特殊意义"], "a": "B", "e": "多分支→(1)增加溶解度(非螺旋→无定形→不沉淀);(2)增加非还原端→磷酸化酶多点攻击→糖原快速释放G-1-P→快速供能。", "kp": null}, {"id": "sugar2_mcq_25", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "丙酮酸羧化酶需要什么辅基?", "o": ["A. TPP", "B. FAD", "C. 生物素(Biotin)", "D. NAD+"], "a": "C", "e": "丙酮酸羧化酶(线粒体)→依赖Biotin→偶联CO2转运→临时存放CO2为羧基化使用→ATP消耗→不可逆→推动糖异生。Biotin缺乏→糖异生↓→低血糖。", "kp": null}, {"id": "sugar2_mcq_26", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "葡萄糖-6-磷酸酶(G-6-Pase)的亚细胞定位?", "o": ["A. 细胞质", "B. 线粒体内膜", "C. 肝脏/肾脏内质网", "D. 溶酶体"], "a": "C", "e": "G-6-Pase定位在肝/肾内质网膜→水解G-6-P→G+Pi→G经ER管进入血液。肌肉无G-6-Pase→肌糖原不能为其他组织提供G。", "kp": null}, {"id": "sugar2_mcq_27", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "糖原合成引物蛋白是什么?", "o": ["A. 胰岛素", "B. 糖原引物蛋白(Glycogenin)", "C. 磷酸化酶", "D. 淀粉酶"], "a": "B", "e": "Glycogenin→自身携带少量Glc→作为糖原合成的起始引物→合酶在此引物基上延伸→逐步构建大分子糖原→成核作用(primer蛋白)。", "kp": null}, {"id": "sugar2_mcq_28", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "PPP水解为何可使UDPG合成不可逆?", "o": ["A. PPP直接产ATP", "B. PPi+H2O→2Pi(焦磷酸酶)→使平衡右移,与DNA/RNA合成类似", "C. PPP抑制合成", "D. 无关"], "a": "B", "e": "UDPG焦磷酸化酶:UTP+G-1-P→UDPG+PPi。PPi+H2O→无机焦磷酸酶→2Pi→反应强烈右移→糖原合成定向进行。DNA/RNA聚合酶同机理!", "kp": null}, {"id": "sugar2_mcq_29", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "果糖二磷酸酶(FBPase-1)的作用是什么?", "o": ["A. 糖原合成", "B. F-1,6-BP→F-6-P+Pi,糖异生限速酶之一", "C. F-6-P→F-1,6-BP", "D. G→G-6-P"], "a": "B", "e": "FBPase-1→F-1,6-BP→F-6-P+Pi→绕过PFK。受AMP和F-2,6-BP抑制(与PFK相反)→保证EMP/糖异生不空转。", "kp": null}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}], "mcq": [{"id": "sugar2_mcq_1", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖原合成中,活化的葡萄糖供体是什么?", "o": ["A. G-1-P", "B. UDP-葡萄糖(UDPG)", "C. G-6-P", "D. ADP-葡萄糖"], "a": "B", "e": "UDPG(尿苷二磷酸葡萄糖)是动物糖原合成的活性Glc供体。PPP水解→不可逆!", "kp": "sugar2_s0_2"}, {"id": "sugar2_mcq_2", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖原合酶的功能是什么?", "o": ["A. 水解α-1,4糖苷键", "B. 形成α-1,4糖苷键延伸", "C. 形成α-1,6分支键", "D. 活化葡萄糖"], "a": "B", "e": "糖原合酶催化UDPG+引物→α-1,4键延伸。磷酸化后失活→受胰岛素去磷酸化激活。", "kp": "sugar2_s0_3"}, {"id": "sugar2_mcq_3", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "分支酶如何处理糖原合成中的α-1,6键?", "o": ["A. 直接连接Glc到OH-6", "B. 切断6-7个G残基段+转移到OH-6", "C. 水解α-1,6键", "D. 不需要分支酶"], "a": "B", "e": "分支酶切下6-7个Glc的α-1,4段→转移至OH-6→形成α-1,6分支。增加分支→增溶解性+增非还原端数!", "kp": "sugar2_s0_4"}, {"id": "sugar2_mcq_4", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "植物淀粉合成使用的活化Glc载体是什么?", "o": ["A. UDPG", "B. ADPG(腺苷二磷酸葡萄糖)", "C. G-1-P", "D. CDPG"], "a": "B", "e": "植物淀粉合成→ADPG;动物糖原→UDPG。两种不同的核苷酸糖载体,体现进化差异。", "kp": "sugar2_s0_5"}, {"id": "sugar2_mcq_5", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "蔗糖合成的主要途径是什么?", "o": ["A. UDPG+F→蔗糖+UDP", "B. UDPG+F-6-P→6-磷酸蔗糖→蔗糖+Pi", "C. G+F→蔗糖", "D. G-1-P+F→蔗糖"], "a": "B", "e": "主途:UDPG+F-6-P→磷酸蔗糖合酶→6-磷酸蔗糖→6-P蔗糖磷酸酶+Pi→蔗糖。磷酸蔗糖合酶是主要调控酶。", "kp": "sugar2_s0_8"}, {"id": "sugar2_mcq_6", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖异生(Gluconeogenesis)的定义是什么?", "o": ["A. G→丙酮酸", "B. 非糖物质→葡萄糖/糖原", "C. 糖原→G-1-P", "D. G→G-6-P"], "a": "B", "e": "糖异生=丙酮酸/乳酸/甘油/生糖aa等→Glc或糖原。基本为EMP逆过程(需绕过3个不可逆步→消耗6-7个~P)。", "kp": "sugar2_s0_9"}, {"id": "sugar2_mcq_7", "mod": "模块一：糖的合成代谢与糖异生", "modI": 0, "q": "糖异生绕过酵解中哪个酶的步骤需要两次反应?", "o": ["A. 己糖激酶", "B. PFK", "C. 丙酮酸激酶(PK)→需两酶绕行", "D. 醛缩酶"], "a": "C", "e": "绕过PK需两步:①丙酮酸→OAA(丙酮酸羧化酶,线粒体,生物素);②OAA→PEP(PEPCK,胞质)。总需1ATP+1GTP。", "kp": "sugar2_s0_13"}, {"id": "sugar2_mcq_8", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "糖异生的关键限速酶之一FBPase-1受何种物质抑制?", "o": ["A. ATP", "B. AMP和F-2,6-BP", "C. NADH", "D. 乙酰CoA"], "a": "B", "e": "FBPase-1受AMP和F-2,6-BP抑制,与PFK-1恰好相反(AMP/2,6-BP激活PFK)。保证EMP或糖异生单向运行!", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_9", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "G-6-Pase(葡萄糖-6-磷酸酶)存在于哪个组织?", "o": ["A. 所有组织", "B. 肝和肾(肌肉无)", "C. 仅肌肉", "D. 仅脑"], "a": "B", "e": "G-6-Pase仅在肝/肾内质网→水解G-6-P→G+Pi→释G入血。肌肉无→肌糖原不能释放G直接供血→只能利己用。", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_10", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "1分子G经EMP产2ATP,而糖异生产1G消耗多少高能磷酸键?", "o": ["A. 2ATP", "B. 4-5~P(4ATP+2GTP=约7高能键)", "C. 6-7~P(净亏4-5)", "D. 8-10~P"], "a": "C", "e": "糖异生:4ATP+2GTP=含7个高能磷酸键(2GTP中的~P计为2个~键)。EMP产2ATP→净亏4-5个~P。高能耗保证代谢高效单向性。", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_11", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "作为糖异生前体,乳酸来自哪个循环?", "o": ["A. 葡萄糖-丙氨酸循环", "B. Cori循环(乳酸循环)", "C. TCA循环", "D. PPP"], "a": "B", "e": "Cori循环:肌肉乳酸→血→肝→乳酸→糖异生→G→肌肉。乳酸是糖异生主要前体(激烈运动后明显)。", "kp": "sugar2_s1_0"}, {"id": "sugar2_mcq_12", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "酵解中的最重要调控酶是什么?", "o": ["A. 己糖激酶", "B. PFK-1(磷酸果糖激酶)★", "C. GAPDH", "D. PK"], "a": "B", "e": "PFK-1是EMP最重要调控点→被ATP/H+/柠檬酸抑制;被AMP/ADP/F-2,6-BP激活。别构调控的教科书级别酶!", "kp": "sugar2_s1_3"}, {"id": "sugar2_mcq_13", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "F-2,6-BP对PFK-1的作用是什么?", "o": ["A. 竞争性抑制", "B. 增强F-6-P亲和力→克服ATP/柠檬酸抑制", "C. 促进PFK-1降解", "D. 作为底物"], "a": "B", "e": "F-2,6-BP使PFK活性vsF-6-P浓度曲线左移→大大提高亲和力→解除ATP/柠檬酸抑制。最强别构激活剂!", "kp": "sugar2_s1_1"}, {"id": "sugar2_mcq_14", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "TCA环最重要的调控酶是什么?", "o": ["A. 柠檬酸合酶", "B. 异柠檬酸脱氢酶★", "C. a-KG脱氢酶", "D. 琥珀酸脱氢酶"], "a": "B", "e": "异柠檬酸脱氢酶→受ADP激活(低能荷信号),NADH/ATP抑制(高能荷信号)。是TCA最重要的调控点→反映细胞能量状态。", "kp": "sugar2_s1_6"}, {"id": "sugar2_mcq_15", "mod": "模块二：血糖调节与糖代谢紊乱", "modI": 1, "q": "能荷(energy charge)反映什么?", "o": ["A. 细胞内CO2浓度", "B. 胞内ATP/ADP/AMP相对含量", "C. 血糖浓度", "D. NAD+/NADH比"], "a": "B", "e": "能荷=([ATP]+0.5[ADP])/([ATP]+[ADP]+[AMP])。能荷大→产能途径减慢;能荷小→产能加速。0~1之间,正常约0.85-0.90。", "kp": "sugar2_s1_7"}, {"id": "sugar2_mcq_16", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "升糖激素包括哪些?", "o": ["A. 仅胰岛素", "B. 肾上腺素(Ad)+胰高血糖素(GL)", "C. 仅甲状腺素", "D. 仅生长激素"], "a": "B", "e": "升糖激素:Ad+GL→G蛋白→AC→cAMP→PKA→级联放大→糖原分解↑→快速升糖。肾上腺和胰高血糖素的协同作用。", "kp": null}, {"id": "sugar2_mcq_17", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "胰岛素的降糖机制之一是什么?", "o": ["A. 激活糖原磷酸化酶", "B. 激活蛋白磷酸酶-1→去磷酸化→激活糖原合酶+抑制磷酸化酶", "C. 促进糖异生", "D. 抑制GLUT4"], "a": "B", "e": "胰岛素→受体Tyr激酶→蛋白磷酸酶-1→去磷酸化→糖原合酶激活(合成↑)+磷酸化酶抑制(降解↓)+GLUT4膜转位(摄入↑)→降血糖。", "kp": null}, {"id": "sugar2_mcq_18", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "正常空腹血糖浓度为多少?", "o": ["A. 50-80mg%", "B. 70-100mg%(3.9-6.1mmol/L)", "C. 120-150mg%", "D. 160-180mg%"], "a": "B", "e": "正常空腹血糖=70-100mg%=3.9-6.1mmol/L。>100mg%=高血糖;>160-180mg%=糖尿病(肾糖阈)。<60-70mg%=低血糖。", "kp": null}, {"id": "sugar2_mcq_19", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "肾糖阈是多少?", "o": ["A. 70-100mg%", "B. 160-180mg%", "C. 120-150mg%", "D. 200mg%以上"], "a": "B", "e": "肾糖阈=160-180mg%(8.9-10mmol/L)→超过此浓度→肾小管重吸收能力饱和→尿中排出糖→糖尿。糖尿病患者超过肾糖阈出现糖尿。", "kp": null}, {"id": "sugar2_mcq_20", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "糖尿病导致酮血症的原因是什么?", "o": ["A. 肝脂肪合成↑", "B. 胰岛素缺乏→G氧化↓→过量乙酰CoA→酮体↑→酸中毒", "C. 糖原合成↑", "D. PPP↑"], "a": "B", "e": "胰岛素缺乏→细胞无法充分利用糖→代偿性脂肪分解→脂肪酸β-氧化→大量乙酰CoA积累→HMG-CoA→酮体↑(β-羟基丁酸/乙酰乙酸/丙酮)→代谢性酸中毒!", "kp": null}, {"id": "sugar2_mcq_21", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "低血糖症的临界血糖值是?", "o": ["A. 60-70mg%以下", "B. 80-90mg%", "C. 100-120mg%", "D. 160-180mg%"], "a": "A", "e": "血糖<60-70mg%=低血糖。<45mg%→脑功能障碍→头痛/昏迷(脑主要依赖G供能)。主要因胰岛素过量或皮质激素不足。", "kp": null}, {"id": "sugar2_mcq_22", "mod": "模块三：血糖调节·考题练习", "modI": 2, "q": "糖皮质激素的生理作用是什么?", "o": ["A. 促进酵解", "B. 促进糖异生+减少组织糖利用→维持血糖", "C. 促进糖原合成", "D. 促进胰岛素分泌"], "a": "B", "e": "糖皮质激素→促进糖异生(诱导PEPCK/FBPase-1)+减少组织糖利用→维持血糖。此机制解释了肾上腺皮质功能减退→低血糖的原因。", "kp": null}, {"id": "sugar2_mcq_23", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "淀粉合成与糖原合成的一个重要区别是什么?", "o": ["A. 完全相同", "B. 淀粉可双向延伸(还原+非还原端),糖原仅单向(非还原端)", "C. 糖原可双向延伸", "D. 都不需要引物"], "a": "B", "e": "淀粉合酶可在非还原端或还原端加入Glc→双向延伸。糖原合酶仅从非还原端延伸→单向。需要引物(小糖原)启动。", "kp": null}, {"id": "sugar2_mcq_24", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "分支酶/糖原Q酶的生理意义?", "o": ["A. 仅提高寡糖甜度", "B. 增加溶解度+增加非还原端数→加快降解/合成速率", "C. 仅有结构作用", "D. 无特殊意义"], "a": "B", "e": "多分支→(1)增加溶解度(非螺旋→无定形→不沉淀);(2)增加非还原端→磷酸化酶多点攻击→糖原快速释放G-1-P→快速供能。", "kp": null}, {"id": "sugar2_mcq_25", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "丙酮酸羧化酶需要什么辅基?", "o": ["A. TPP", "B. FAD", "C. 生物素(Biotin)", "D. NAD+"], "a": "C", "e": "丙酮酸羧化酶(线粒体)→依赖Biotin→偶联CO2转运→临时存放CO2为羧基化使用→ATP消耗→不可逆→推动糖异生。Biotin缺乏→糖异生↓→低血糖。", "kp": null}, {"id": "sugar2_mcq_26", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "葡萄糖-6-磷酸酶(G-6-Pase)的亚细胞定位?", "o": ["A. 细胞质", "B. 线粒体内膜", "C. 肝脏/肾脏内质网", "D. 溶酶体"], "a": "C", "e": "G-6-Pase定位在肝/肾内质网膜→水解G-6-P→G+Pi→G经ER管进入血液。肌肉无G-6-Pase→肌糖原不能为其他组织提供G。", "kp": null}, {"id": "sugar2_mcq_27", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "糖原合成引物蛋白是什么?", "o": ["A. 胰岛素", "B. 糖原引物蛋白(Glycogenin)", "C. 磷酸化酶", "D. 淀粉酶"], "a": "B", "e": "Glycogenin→自身携带少量Glc→作为糖原合成的起始引物→合酶在此引物基上延伸→逐步构建大分子糖原→成核作用(primer蛋白)。", "kp": null}, {"id": "sugar2_mcq_28", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "PPP水解为何可使UDPG合成不可逆?", "o": ["A. PPP直接产ATP", "B. PPi+H2O→2Pi(焦磷酸酶)→使平衡右移,与DNA/RNA合成类似", "C. PPP抑制合成", "D. 无关"], "a": "B", "e": "UDPG焦磷酸化酶:UTP+G-1-P→UDPG+PPi。PPi+H2O→无机焦磷酸酶→2Pi→反应强烈右移→糖原合成定向进行。DNA/RNA聚合酶同机理!", "kp": null}, {"id": "sugar2_mcq_29", "mod": "模块四：糖合成与糖异生·考题练习", "modI": 3, "q": "果糖二磷酸酶(FBPase-1)的作用是什么?", "o": ["A. 糖原合成", "B. F-1,6-BP→F-6-P+Pi,糖异生限速酶之一", "C. F-6-P→F-1,6-BP", "D. G→G-6-P"], "a": "B", "e": "FBPase-1→F-1,6-BP→F-6-P+Pi→绕过PFK。受AMP和F-2,6-BP抑制(与PFK相反)→保证EMP/糖异生不空转。", "kp": null}], "judge": [], "fill": [{"id": "sugar2_fill_1", "modI": 0, "q": "糖原合成中,葡萄糖被活化为________,它是________(核苷酸)的高能衍生物。", "a": "UDPG(尿苷二磷酸葡萄糖),UTP", "kp": "sugar2_s0_2"}, {"id": "sugar2_fill_2", "modI": 0, "q": "糖原合酶催化________键的形成,分支酶催化________键的形成。", "a": "α-1,4,α-1,6", "kp": "sugar2_s0_3"}, {"id": "sugar2_fill_3", "modI": 0, "q": "糖异生绕过酵解中三个不可逆反应分别需要________(跳过丙酮酸激酶)、________(跳过PFK-1)和________(跳过己糖激酶)。", "a": "丙酮酸羧化酶+PEPCK,果糖二磷酸酶(FBPase-1),葡萄糖-6-磷酸酶(G-6-Pase)", "kp": "sugar2_s0_12"}, {"id": "sugar2_fill_4", "modI": 1, "q": "酵解最重要的调控酶是________,它被________(促进因子)激活,被________和________(抑制因子)抑制。", "a": "磷酸果糖激酶(PFK-1),AMP/F-2,6-BP,ATP,柠檬酸", "kp": "sugar2_s1_2"}, {"id": "sugar2_fill_5", "modI": 2, "q": "TCA环最重要的调控酶是________,被________激活,被________抑制。", "a": "异柠檬酸脱氢酶,ADP,NADH/ATP", "kp": null}, {"id": "sugar2_fill_6", "modI": 1, "q": "正常空腹血糖浓度为________mg%即________mmol/L。肾糖阈为________mg%。", "a": "70-100,3.9-6.1,160-180", "kp": "sugar2_s1_0"}, {"id": "sugar2_fill_7", "modI": 1, "q": "升糖激素主要为________和________,两者通过________信号通路触发糖原分解。", "a": "肾上腺素(Ad),胰高血糖素(GL),cAMP-PKA级联放大", "kp": "sugar2_s1_1"}, {"id": "sugar2_fill_8", "modI": 1, "q": "Cori循环中,肌肉酵解产生________,经血液运至________,经________途径生成葡萄糖回到肌肉。", "a": "乳酸,肝脏,糖异生", "kp": "sugar2_s1_6"}, {"id": "sugar2_fill_9", "modI": 0, "q": "植物淀粉合成采用________作为活化Glc载体,与动物UDPG不同;直链淀粉合成采用________支链淀粉需________酶形成α-1,6分支。", "a": "ADPG(腺苷二磷酸葡萄糖),ADPG,Q", "kp": "sugar2_s0_5"}, {"id": "sugar2_fill_10", "modI": 1, "q": "1分子葡萄糖经酵解净产________ATP,而2分子丙酮酸经糖异生合成1分子葡萄糖消耗约________ATP,净亏约________ATP以保证代谢双向性。", "a": "2,6-7,4-5", "kp": "sugar2_s1_4"}], "short": [{"id": "sugar2_short_1", "modI": 0, "q": "简述糖原合成的全过程(葡萄糖活化、主链延伸和分支形成)。", "a": "糖原合成共三阶段:\u000b\u000b①葡萄糖活化:G→己糖激酶→G-6-P→变位酶→G-1-P+UTP→UDPG焦磷酸化酶→UDPG+PPi(Pi焦磷酸酶→2Pi→不可逆!)\u000b\u000b②α-1,4主链延伸:UDPG+引物(糖原引物蛋白携带)→糖原合酶→α-1,4键延伸+UDP→重复循环→线性链增长→仅从非还原端延伸\u000b\u000b③α-1,6分支形成:分支酶→切下6-7个Glc的α-1,4段→转移到OH-6→形成α-1,6分支→多分支+多非还原端→利于快速动员\u000b\u000b糖原合酶受胰岛素去磷酸化激活→进食后促进糖原储存", "kp": "sugar2_s0_2"}, {"id": "sugar2_short_2", "modI": 1, "q": "简述糖异生绕过EMP三个不可逆步骤的机制和关键酶。", "a": "糖异生基本是EMP逆过程→但三步不可逆必须绕过:\u000b\u000b绕过PK(PEP→丙酮酸):需两步反应\u000b①线粒体:丙酮酸+CO2+ATP→丙酮酸羧化酶(生物素辅基)→OAA+ADP+Pi\u000b②胞质:OAA→苹果酸→出线粒体→OAA+GTP→PEPCK→PEP+CO2+GDP\u000b共需:1ATP+1GTP\u000b\u000b绕过PFK-1:F-1,6-BP+H2O→FBPase-1→F-6-P+Pi(受AMP/F-2,6-BP抑制)\u000b\u000b绕过己糖激酶:G-6-P+H2O→G-6-Pase(内质网,肝/肾特有)→G+Pi→释放入血\u000b\u000b总消耗:4ATP+2GTP(~7个~P)→等价4-5ATP→代谢高效单向性", "kp": "sugar2_s1_6"}, {"id": "sugar2_short_3", "modI": 2, "q": "简述PFK-1的别构调控机制和F-2,6-BP的作用。", "a": "PFK-1是EMP最重要调控酶(四聚体,每亚基319aa):\u000b\u000b抑制因子:\u000b• ATP↑→与别构位点结合→降低F-6-P亲和力→EMP↓(高能荷反馈)\u000b• 柠檬酸↑→增强ATP抑制→EMP↓(TCA产物反馈)\u000b• H+↑→抑制→过量乳酸堆积→自我保护\u000b\u000b激活因子:\u000b• AMP/ADP↑→与ATP竞争别构位点→EMP↑(低能荷信号)\u000b• F-2,6-BP↑→最强激活剂→结合别构位点→显著增加F-6-P亲和力→曲线左移→消除ATP/柠檬酸抑制\u000b• F-2,6-BP由PFK-2合成→受胰岛素(↑)和胰高血糖素(↓)调控\u000b\u000b生理整合:进食后胰岛素↑→F-2,6-BP↑→EMP↑;饥饿时GL↑→F-2,6-BP↓→EMP↓→允许脑有更多G", "kp": null}, {"id": "sugar2_short_4", "modI": 1, "q": "比较升糖激素(Ad/GL)和降糖激素(胰岛素)对糖代谢的调控机理。", "a": "升糖激素(Ad/GL)—cAMP-PKA级联:\u000b①激素→与G蛋白受体结合→腺苷酸环化酶→cAMP↑\u000b②cAMP→PKA→磷酸化靶蛋白:\u000b• 糖原磷酸化酶→磷酸化→活化→糖原→G-1-P→G进入血\u000b• 糖原合酶→磷酸化→失活→糖原合成↓\u000b• PEPCK/FBPase-1→转录诱导→糖异生↑\u000b③级联放大:1激素分子→百万G→快速升糖\u000b\u000b降糖激素(胰岛素)—Tyr激酶→磷酸酶:\u000b①Ins→受体Tyr激酶→多条信号通路\u000b②蛋白磷酸酶-1→去磷酸化:\u000b• 磷酸化酶→去磷酸→失活→糖原分解↓\u000b• 糖原合酶→去磷酸→激活→糖原合成↑\u000b③PKB→GLUT4膜转位→G摄入↑\u000b④EMP酶→转录诱导→G氧化↑\u000b\u000b净效果:Ad/GL→血糖↑;胰岛素→血糖↓→两者拮抗维持血糖稳态", "kp": "sugar2_s1_2"}, {"id": "sugar2_short_5", "modI": 1, "q": "简述血糖的来源、去路及稳态调控机制。", "a": "血糖正常范围:70-100mg%(3.9-6.1mmol/L)。\u000b\u000b血糖来源(输入):\u000b①食物消化吸收→G→小肠→门静脉→肝\u000b②肝糖原分解→G(肝G-6-Pase)→释放入血\u000b③糖异生→乳酸/甘油/生糖aa→G(肝/肾)→入血\u000b\u000b血糖去路(输出):\u000b①各组织氧化→EMP→TCA→CO2+H2O+大量ATP\u000b②肝/肌糖原合成→储存\u000b③转化为脂肪→脂肪酸合成\u000b④>肾糖阈(160-180mg%)→尿糖排出\u000b\u000b激素调控:\u000b• 低血糖(<70-100)→Ad/GL↑→cAMP→糖原分解+糖异生↑\u000b• 高血糖(>120-150)→Ins↑→氧化↑+合成↑+摄入↑\u000b• 应激→Ad↑→快速动员糖原供战\u000b植物无此激素系统→代谢调控靠非激素微调", "kp": "sugar2_s1_3"}, {"id": "sugar2_short_6", "modI": 2, "q": "简述TCA环中三个不可逆酶的调控机制。", "a": "TCA三调控点与三个不可逆酶对应:\u000b\u000b①柠檬酸合酶:\u000b• 底物:OAA浓度↑→激活(最重要调节→OAA浓度决定了合酶活性)\u000b• 产物:柠檬酸/NADH/ATP↑→抑制→反馈↓\u000b• 抑制剂:琥珀酰CoA→竞争结合\u000b\u000b②异柠檬酸脱氢酶★(最关键调控点):\u000b• 激活剂:ADP↑(低能荷)→别构激活→TCA↑→产能↑\u000b• 抑制剂:NADH/ATP↑(高能荷)→抑制→TCA↓→节约原料\u000b• Ca2+↑→激活(呼应肌肉收缩、代谢增强等能量需求→TCA加速)\u000b\u000b③α-KG脱氢酶系:\u000b• 与PDH类似→受磷酸化/去磷酸化调控\u000b• NADH/琥珀酰CoA↑→抑制;Ca2+→激活\u000b\u000b总体逻辑:细胞ATP含量调控TCA速率→高ATP时TCA减慢,低ATP时TCA加速→维持能量稳态", "kp": null}, {"id": "sugar2_short_7", "modI": 1, "q": "简述糖尿病两类分型的生化机制差异。", "a": "糖尿病基本机制:胰岛素信号通路障碍→细胞G利用↓→血G↑。\u000b\u000b1型糖尿病(T1D):\u000b• 病因:胰岛β细胞被自身免疫攻击→绝对胰岛素缺乏\u000b• 发病:幼儿/青少年期→急\u000b• 机制:无Ins→无法激活糖原合成/EMP/脂肪合成↓→所有代谢退化\u000b• 治疗:必须外源补给胰岛素(注射)→依靠注入Ins+监测血糖\u000b\u000b2型糖尿病(T2D):\u000b• 病因:胰岛素血中存在但细胞受体异常→胰岛素抵抗\u000b• 发病:中老年→渐进,与生活方式相关(更多)\u000b• 机制:受体后缺陷→如GLUT4不能膜转位→细胞摄入G能力↓\u000b  →高G刺激胰B细胞→高Ins环境→长期→β细胞衰减→最终可有胰岛素缺发\u000b• 治疗:非药→生活方式干预;药→提高Ins敏感性\u000b\u000b相同后果:两大类型均导致:\u000b• G氧化↓→脂肪替代产能→酮体↑→酸中毒\u000b• 长期高血糖→蛋白质糖基化→血管病变、肾病等并发症", "kp": "sugar2_s1_6"}], "calc": [{"id": "sugar2_calc_1", "modI": 0, "q": "计算1分子乳酸在肝中经糖异生生成葡萄糖消耗多少高能磷酸键？净消耗多少？", "a": "净消耗约4~P", "steps": "①2乳酸→2丙酮酸(LDH):0个~P(NADH再氧化,不耗能)\u000b②2丙酮酸→2OAA(丙酮酸羧化酶):2×1ATP=2~P\u000b③2OAA→2PEP(PEPCK):2×1GTP=2~P\u000b④2PEP→...→F-1,6-BP:需1ATP=1~P\u000b⑤F-1,6-BP→F-6-P(FBPase-1):0~P\u000b⑥G-6-P→G(G-6-Pase):0高能键\u000b\u000b总计:2+2+1=5~P\u000b但乳酸→丙酮酸产生的NADH可被利用(3ATP当量)\u000b\u000b可用计算:5~P-2NADH(≈5ATP)=净约0~P(NADH能量抵消)\u000b实际消耗:4-5~P\u000b\u000b与EMP对比:1G→2乳酸=2ATP→2乳酸→1G消耗~4ATP→净亏~2ATP", "kp": "sugar2_s0_15"}, {"id": "sugar2_calc_2", "modI": 1, "q": "计算1分子葡萄糖-6-磷酸进入糖原合成最终储存为糖原,消耗几个高能磷酸键？与G→糖原相比有何区别？", "a": "仅1个~P(G→G-6-P需1ATP,糖原储存不需另外的~P),比G→糖原更节省能量", "steps": "G-6-P→糖原:\u000b①G-6-P→G-1-P(变位酶):0~P\u000b②G-1-P+UTP→UDPG+PPi:0~P(PPi水解推动→等价消耗1~P)\u000b③UDPG+引物→糖原合酶→糖原+UDP:0~P\u000b\u000bUDP相当于已活化→一次UDP代表已付1个~P\u000b\u000b若从G开始:\u000b①G→G-6-P:1ATP(1~P)\u000b②G-6-P→G-1-P:0~P\u000b③G-1-P+UTP→UDPG:等价1~P\u000b④糖原储存:0~P\u000b\u000b总计:2~P(从G→糖原储存一个Glc残留)\u000b\u000b而G-6-P直接进糖原储存仅需1~P(UTP生成步)\u000b→G-6-P→糖原比G→糖原节省1个~P", "kp": "sugar2_s1_1"}, {"id": "sugar2_calc_3", "modI": 1, "q": "论述Cori循环(乳酸循环)的完整过程及能量平衡,计算1分子葡萄糖经Cori循环两次往返后的总消耗。", "a": "两次Cori往返净亏损28ATP", "steps": "Cori循环一次往返:\u000b肌肉:1G→2乳酸+2ATP(酵解产)+2NADH(c)\u000b肝脏:2乳酸+6ATP→1G(糖异生消耗)\u000b\u000b能量平衡:\u000b肌肉产:2ATP\u000b肝脏耗:6ATP\u000b净亏:4ATP/一往返(肌肉获得的ATP代价4倍)\u000b但2NADH(c)产的ATP(5或3)在其他组织中利用\u000b\u000b两次往返:\u000b含两个细胞的各两次循环,总消耗=\u000b双细胞×2(酵解-糖异生)往返=4(耗4ATP×2次×1分子=4ATP?错了)\u000b\u000b正确:2分子G→2次酵解=4ATP生成\u000b2次糖异生=12ATP消耗\u000b净亏:8ATP(不计NADH促进的额外ATP)\u000b加上NADH进入呼吸链的差值:\u000b2次糖异生需2×2NADH=4NADH→可选进行→减少净亏损\u000b实际净亏:约28ATP(两往返)×? 实际:\u000b\u000b一往返亏损4(纯细胞ATP)+两NADH价值=5→净盈余1~ATP\u000b或甘油-3-P穿梭→两循环亏损4×3=12-乳酸→糖异生再耗多\u000b\u000b说明Cori循环是紧急供能,能量代价巨大但能保障脑/心获得所需G", "kp": "sugar2_s1_1"}, {"id": "sugar2_calc_4", "modI": 0, "q": "计算1分子生糖氨基酸(Ala)经糖异生生成葡萄糖后,在肌肉中酵解为乳酸→再回肝脏糖异生→共消耗多少ATP？", "a": "一完整Cori循环净亏损约4ATP;从Ala起始再加-1ATP→净亏5ATP", "steps": "Ala→肝→糖异生→G:\u000b①Ala+α-KG→丙酮酸+Glu(ALT):0~P\u000b②丙酮酸→糖异生→G:消耗6ATP\u000b\u000b肌肉:1G→2乳酸+2ATP\u000b\u000b肝脏:2乳酸+6ATP→1G\u000b\u000bCori循环往返:\u000b肌肉产:2ATP\u000b肝脏耗:6ATP\u000b净亏:4ATP(但肌肉获2ATP→但整个系统净4个~P)\u000b\u000bAla→G→乳酸→G再循环:\u000b1.Ala→G:6ATP消耗\u000b2.肌肉得G→2ATP产\u000b3.乳酸→G:6ATP消耗\u000b\u000b持续循环总消耗:12-2=10ATP/每最终血中G\u000b但提供G→肌肉→消耗氧化→总保持10代谢代价得到2ATP\u000b极高代价→Cori循环主要发生在紧急/运动→非正常生理状态", "kp": "sugar2_s0_9"}, {"id": "sugar2_calc_5", "modI": 1, "q": "论述PFK-1同时被ATP别构抑制和F-2,6-BP别构激活的整合调控机制。", "a": "PFK-1是EMP的核心调控枢纽,整合多信号决定EMP速率", "steps": "PFK-1是EMP的核心调控枢纽,整合多信号决定EMP速率", "kp": "sugar2_s1_0"}], "term": [{"id": "sugar2_term_1", "modI": 0, "term": "UDPG(尿苷二磷酸葡萄糖)", "def": "①UDPG=尿苷二磷酸葡萄糖→动物糖原合成的活化葡萄糖载体（定义）。②合成:G-1-P+UTP→UDPG+PPi(UDPG焦磷酸化酶→PPi+H2O→无机焦磷酸酶→2Pi→不可逆!)（合成+能源）。③功能:作为高能葡萄糖基供体→糖原合酶→每步加一个Glc残基+释放UDP（功能）。④与G-1-P不同:G-1-P含磷酸基团但非高能→UDPG的糖苷键能量高→足以推动糖原延伸（与G-1-P的区别）。⑤与ADPG、CDPG等相似→植物使用ADPG为淀粉合成活化载体（植物差异）。", "kps": "①定义(1分)②合成反应+焦磷酸酶(1分)③高能糖基载体(1分)④与G-1-P区别(1分)⑤植物ADPG(1分)", "kp": "sugar2_s0_2"}, {"id": "sugar2_term_2", "modI": 0, "term": "糖原合酶(Glycogen Synthase)", "def": "①催化UDPG中Glc残基转移至引物(糖原引物蛋白)的非还原端→形成α-1,4糖苷键的酶（定义+反应）。②仅从非还原端延伸→不可逆且单向（方向）。③引物需要糖原引物蛋白(Glycogenin)提供起始糖基→早期糖原合成在此蛋白上完成（引物）。④受磷酸化调控:胰岛素→蛋白磷酸酶-1→去磷酸化→合酶激活=糖原合成↑;肾上腺素→PKA→磷酸化→合酶失活=合成↓（调控）。⑤与动物UDPG/植物ADPG关系的不同（植物差异）。", "kps": "①定义+反应(1分)②单向延伸(1分)③引物蛋白(1分)④磷酸化调控(2分)⑤与植物对比(1分)", "kp": "sugar2_s0_3"}, {"id": "sugar2_term_3", "modI": 0, "term": "分支酶(Branching Enzyme)", "def": "①糖原合成中催化α-1,6分支键形成的酶（定义）。②过程:切下一段6~7个Glc的α-1,4线性链→将这段转移到同链或邻链的Glc-OH-6→形成α-1,6分支键（机制）。③意义:增加糖原溶解度(非螺旋无定形→不沉淀)→增加非还原端数目(多分支→多点酶切→快速释放Glc)（双重意义）。④与Q酶不同:分支酶处理糖原(每8-12分支)而Q酶处理支链淀粉(每25-30分支)（区别）。⑤缺陷可导致糖原结构异常→糖原贮积病（临床）。", "kps": "①定义(1分)②切断6-7段+转移(1分)③双重意义(1分)④与Q酶区别(1分)⑤临床意义(1分)", "kp": "sugar2_s0_4"}, {"id": "sugar2_term_4", "modI": 0, "term": "ADPG(腺苷二磷酸葡萄糖)", "def": "①ADPG=腺苷二磷酸葡萄糖→植物淀粉合成的活化葡萄糖载体（定义）。②合成:G-1-P+ATP→ADPG+PPi→焦磷酸酶水解(Pi)使反应不可逆（合成）。③功能:作为高能葡萄糖基供体→淀粉合酶→在非还原端或还原端加入Glc→双向延伸(与糖原仅单向不同)（功能+特征）。④与UDPG不同:核苷酸载体不同(UDPG vs ADPG)→植物/动物取不同的核苷酸载体（进化差异）。⑤ADPG焦磷酸化酶是淀粉合成限速酶→受代谢调控（调控）。", "kps": "①定义(1分)②合成反应(1分)③双向延伸(1分)④与UDPG核苷酸差异(1分)⑤调控(1分)", "kp": "sugar2_s0_2"}, {"id": "sugar2_term_5", "modI": 1, "term": "糖异生(Gluconeogenesis)", "def": "①非糖物质(丙酮酸/乳酸/甘油/生糖氨基酸)转化生成葡萄糖或糖原的过程（定义）。②部位:肝脏(主要)+肾脏皮质（部位）。③需绕过EMP 3个不可逆步:丙酮酸→OAA(丙酮酸羧化酶+生物素)→PEP(PEPCK)→绕过PK;F-1,6-BP→F-6-P(FBPase-1)→绕过PFK;G-6-P→G(G-6-Pase)→绕过HK（绕道机制）。④能量:2丙酮酸→1G消耗4ATP+2GTP=约6-7~P→净亏4-5~P→保证代谢单向性（能耗）。⑤意义:维持血糖→供应脑组织(>100gG/日)→紧急供能→回收乳酸等废物回收（意义）。", "kps": "①定义(1分)②肝/肾(1分)③绕过三步(2分)④能耗(1分)⑤多种意义(1分)", "kp": "sugar2_s1_7"}, {"id": "sugar2_term_6", "modI": 1, "term": "丙酮酸羧化酶(Pyruvate Carboxylase, PC)", "def": "①催化丙酮酸+CO2+ATP→草酰乙酸(OAA)+ADP+Pi→不可逆→糖异生起始酶（定义+反应）。②部位:线粒体基质→草酰乙酸生成处→OAA→苹果酸→穿出线粒体→胞质（部位+通路）。③辅基:生物素(Biotin=A维生素B7)→共价结合Lys→捕获CO2并转移至丙酮酸以获得羧基（辅基）。④调控:受乙酰CoA别构激活(储脂→β-氧化→乙酰CoA↑→糖异生↑→应对能量需求)（调控）。⑤缺陷→低血糖+乳酸性酸中毒+神经系统损伤→婴儿危症（临床）。", "kps": "①反应式(1分)②线粒体(1分)③生物素辅基(1分)④乙酰CoA激活(1分)⑤临床缺陷(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_7", "modI": 1, "term": "PEPCK(磷酸烯醇式丙酮酸羧激酶)", "def": "①糖异生第二步绕道→催化OAA+GTP(或GDP)→PEP+CO2+GDP(或GTP)→不可逆的脱羧反应（定义+反应）。②位于胞质或线粒体(不同物种)（部位）。③消耗1GTP高能磷酸键→驱动脱羧→使OAA转变回PEP→完成绕过PK（能耗）。④PEPCK表达受糖皮质激素诱导(饥饿)→增加糖异生→促进肝糖输出→维持血糖（调控）。⑤与PC协同:PC提供OAA→PEPCK转化为PEP→回入EMP逆向步骤（与PC的关系）。", "kps": "①定义+反应(1分)②胞质位点(1分)③GTP消耗(1分)④激素调控(1分)⑤与PC协同(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_8", "modI": 1, "term": "FBPase-1(果糖-1,6-二磷酸酶-1)", "def": "①糖异生的关键限速酶之一→F-1,6-BP+H2O→F-6-P+Pi→绕过EMP中PFK（定义+反应）。②受AMP强抑制(低能荷)→F-2,6-BP抑制（调节）。③PFK-1与此完全相反:AMP/F-2,6-BP→激活↓→EMP与糖异生的完美对立调控（对应PFK-1的互反关系）。④意义:保证EMP与糖异生不空转→决定代谢通路定向→细胞高效利用底物（意义）。⑤与FBPase-2不同(双功能酶→配EMP/GL激素调控F-2,6-BP浓度)（区分）。", "kps": "①反应(1分)②AMP/F-2,6-BP抑制(1分)③与PFK-1互反(1分)④意义(1分)⑤与FBPase-2区分(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_9", "modI": 1, "term": "G-6-Pase(葡萄糖-6-磷酸酶)", "def": "①G-6-P+H2O→G+Pi在肝/肾内质网膜进行→绕过己糖激酶→糖异生最后一步（定义+反应）。②G-6-Pase定位于内质网→G随后进入血液（部位）。③仅肝和肾存在G-6-Pase→肌肉无→肌肉糖原不能直接释G到循环（组织差异）。④缺陷→Von Gierke病(糖原贮积病I型)→糖原积累+低血糖+乳酸酸中毒（临床）。⑤与己糖激酶的完全逆转关系:己糖激酶→G→G-6-P,  G-6-Pase→G-6-P→G（与己糖激酶的对比）。", "kps": "①反应式(1分)②内质网(1分)③组织差异(1分)④Von Gierke病(1分)⑤与己糖激酶逆转(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_10", "modI": 1, "term": "能荷(Energy Charge)", "def": "①细胞内腺苷酸的高能磷酸状态指标:EC=([ATP]+0.5[ADP])/([ATP]+[ADP]+[AMP])→取值范围0~1（定义+公式）。②高能荷(>0.85):ATP↑→产能途径减慢→合成代谢↑(细胞能量充分)（高能荷状态）。③低能荷(<0.50):AMP↑→产能途径加快→酵解/TCA加速→ATP回补（低能荷状态）。④调控原理:ATP、ADP、AMP相互转化形成三角平衡→任一变化→整个EC变→各代谢途径同时响应→严密协调供能和用能（三角平衡）。⑤正常能荷约0.85-0.90→细胞内精制度量→微调AMP激活的激酶和ATP抑制的调控位点（常态化）。", "kps": "①公式(1分)②高/低能荷状态(1分)③限速酶调控(1分)④三角平衡(1分)⑤正常范围(1分)", "kp": "sugar2_s1_7"}, {"id": "sugar2_term_11", "modI": 1, "term": "PFK-2/FBPase-2(双功能酶)", "def": "①一种兼具两个酶活性的双功能酶→合成/降解F-2,6-BP（定义）。②PFK-2功能:F-6-P+ATP→F-2,6-BP+ADP→F-2,6-BP是PFK-1的最强别构激活剂（合成功能）。③FBPase-2功能:F-2,6-BP+F-6-P→→F-6-P+Pi→降低F-2,6-BP→EMP↓（降级功能）。④磷酸化调控:胰高血糖素→cAMP→PKA→磷酸化→PFK-2活性↓+FBPase-2活性↑→F-2,6-BP↓→EMP↓（饥饿）。胰岛素→去磷酸化→PFK-2↑+FBPase-2↓→F-2,6-BP↑→EMP↑（进食）。⑤一端调控EMP开关→枢纽级位置（意义）。", "kps": "①双功能酶(1分)②PFK-2合成(1分)③FBPase-2降解(1分)④磷酸化调控(1分)⑤EMP开关(1分)", "kp": "sugar2_s1_1"}, {"id": "sugar2_term_12", "modI": 1, "term": "Cori循环(乳酸循环)", "def": "①肌肉与肝之间通过乳酸和葡萄糖的相互转化构成的代谢循环（定义）。②过程:肌肉酵解→G→2乳酸(LDH)+2ATP→乳酸→血液→肝脏→乳酸→丙酮酸→糖异生→G→血液→肌肉→再次酵解（过程）。③能量:肌肉产2ATP,肝糖异生消耗6ATP→净亏4ATP/往返（能量）。④生理意义:废物回收(乳酸解毒)→回收C骨架→维持血糖→保障脑/心供能→极重要意义但代价高（意义）。⑤激烈运动后→乳酸↑→血pH↓→Cori循环加速→乳酸性酸中毒可能（运动生理）。", "kps": "①定义(1分)②完整过程(2分)③能量(1分)④意义(1分)⑤运动联系(1分)", "kp": "sugar2_s1_6"}, {"id": "sugar2_term_13", "modI": 1, "term": "胰岛素受体(Insulin Receptor)", "def": "①细胞膜上结合胰岛素的受体→属于受体酪氨酸激酶(RTK)家族（定义）。②亚基结构:α2β2四聚体→两个α亚基(胞外结合Ins)+两个β亚基(胞内Tyr激酶活性)（结构）。③信号:胰岛素结合α→β亚基自磷酸化(Tyr位点)→激活多条通路:PI3K-Akt→GLUT4膜转位→G摄入↑;MAP→转录诱导EMP/TCA酶↑（信号）。④去糖调控:诱导蛋白质磷酸酶-1→去磷酸化→糖原合酶激活+磷酸化酶失活→糖原合成↑（去糖作用）。⑤抵抗→II型糖尿病→受体后缺陷→严重高血糖（临床）。", "kps": "①RTK家族(1分)②α2β2结构(1分)③PI3K-Akt/PKB通路(1分)④去糖调控(1分)⑤抵抗→T2D(1分)", "kp": "sugar2_s1_2"}, {"id": "sugar2_term_14", "modI": 1, "term": "GLUT4转运蛋白", "def": "①肌细胞和脂肪细胞中胰岛素响应的葡萄糖转运蛋白（定义）。②定位:静息时位于胞内膜泡中→胰岛素刺激→PKB信号→运输至细胞膜→G加快跨膜扩散（机制）。③功能:半饱和G浓度~Km≈5mM→很接近空腹血糖水平→高效转运（效率）。④与GLUT1~3不同:GLUT4为胰岛素调节(动态)→其余为组成型(恒态可用)（差异）。⑤胰岛素缺乏/II型糖尿病→GLUT4不能膜移位→细胞G摄入↓→高血糖（临床）。", "kps": "①定义(1分)②胰岛素→膜移位(1分)③Km约5mM(1分)④与GLUT1-3对比(1分)⑤糖尿病(1分)", "kp": "sugar2_s1_2"}, {"id": "sugar2_term_15", "modI": 1, "term": "肾糖阈(Renal Glucose Threshold)", "def": "①血糖浓度160-180mg%(8.9-10mmol/L)时肾小管重吸收G达到最大→超过此值→G出现在尿中→即糖尿（定义）。②机制:肾小球滤过G→近端小管SGLT二钠Glc共转运蛋白→重吸收G→但最大重吸收速率(TmG)有限(mg/min)（机制）。③正常血糖:70-100mg%→TmG远超滤过量→尿无G→超过10mmol/L→超过TmG→尿糖阳性（正常vs糖尿）。④临床:糖尿病患者检测尿G(+)→但尿G(+)不能确定糖尿病(可见于正常妊娠/肾小管功能异常)（临床）。⑤意义:诊断和监测糖尿效果(血糖可随时间变化而尿糖反映最近几小时血糖水平)（意义）。", "kps": "①定义+阈值浓度(1分)②SGLT重吸收机制(1分)③正常尿无G(1分)④糖尿与TMG(1分)⑤临床意义(1分)", "kp": "sugar2_s1_7"}, {"id": "sugar2_term_16", "modI": 0, "term": "Von Gierke病(糖原贮积病I型)", "def": "①G-6-Pase缺陷导致的最常见的糖原贮积病(常染色体隐性)（定义）。②机制:G-6-Pase缺失→A)不能将G-6-P→G→肝糖原积累; B)低血糖(不能释G); C)代偿性EMP↑→乳酸/乳酸酸中毒（生化）。③积累→肝脾肿大→→肾病风险↑→→生长矮小（临床表现）。④禁食试验:空腹→血糖不降→反而乳酸↑→此病典型特征（诊断）。⑤治疗:频繁多次进食(每2-3小时一餐高淀粉量)+鼻胃夜间持续补充G→限制EMP→延缓并发症（治疗）。", "kps": "①G-6-Pase缺陷(1分)②低血糖+乳酸+糖原累积(1分)③肝肿大+矮小(1分)④实验室特征(1分)⑤治疗原则(1分)", "kp": "sugar2_s0_3"}], "preview": null, "appcards": []};